import { test, expect } from "@playwright/test";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

test.describe("IncompleteExerciseCard Weight Display", () => {
  test("should display previous weights in incomplete exercise cards", async ({
    page,
  }) => {
    await page.goto("/");

    // Close PWA install banner if present
    const closeButton = page
      .locator("button")
      .filter({ hasText: /×|close/i })
      .first();
    if (await closeButton.isVisible()) {
      await closeButton.click();
    }

    // Import the Example-Sheet.xlsx file
    const fileInput = page.locator('input[type="file"]');
    const exampleSheetPath = path.resolve(__dirname, "../Example-Sheet.xlsx");

    // Click the import button to trigger file input
    await page.getByRole("button", { name: /XLSX importieren/i }).click();

    // Upload the file
    await fileInput.setInputFiles(exampleSheetPath);

    // Wait for import to complete
    await expect(page.getByText(/Importiert/i)).toBeVisible({ timeout: 5000 });

    // Wait a bit for data to settle
    await page.waitForTimeout(1000);

    // Define expected exercises with their weights from Example-Sheet.xlsx
    const expectedExercises = [
      { name: "Beinstrecken / Maschine", weight: "190kg" },
      { name: "Bankdrücken / Langhantel", weight: "15kg" },
      { name: "T - Bar Rudern / Maschine", weight: "42.5kg" },
      { name: "Seitheben / Seilzug", weight: "15kg" },
      { name: "Bicepscurls / Kabelturm", weight: "45kg" },
      { name: "Trizepsmaschine", weight: "46kg" },
      { name: "Bauchpressenbank / Maschine", weight: "10kg" },
      { name: "Rückenstrecken / Hz.", weight: "17.5kg" },
      { name: "Waden/ Beinpresse", weight: "120kg" },
      { name: "Unterarm-Curls / Kabelturm", weight: "15kg" },
    ];

    // Check that each incomplete exercise displays its previous weight
    for (const exercise of expectedExercises) {
      const exerciseCard = page
        .locator(`[class*="cursor-pointer"]`)
        .filter({
          hasText: exercise.name,
        })
        .first();

      await expect(exerciseCard).toBeVisible();

      // Check that the weight is visible in the card
      const weightDisplay = exerciseCard.getByText(exercise.weight);
      await expect(weightDisplay).toBeVisible({
        timeout: 3000,
      });

      // Verify weight is positioned on the right (by checking it has absolute positioning)
      const weightElement = await weightDisplay.elementHandle();
      if (weightElement) {
        const box = await weightElement.boundingBox();
        const cardBox = await exerciseCard.boundingBox();

        // Weight should be positioned on the right side of the card
        if (box && cardBox) {
          expect(box.x).toBeGreaterThan(cardBox.x + cardBox.width / 2);
        }
      }
    }
  });

  test("completed exercises should not show weight in absolute position", async ({
    page,
  }) => {
    await page.goto("/");

    // Close PWA install banner if present
    const closeButton = page
      .locator("button")
      .filter({ hasText: /×|close/i })
      .first();
    if (await closeButton.isVisible()) {
      await closeButton.click();
    }

    // Import the Example-Sheet.xlsx file
    const fileInput = page.locator('input[type="file"]');
    const exampleSheetPath = path.resolve(__dirname, "../Example-Sheet.xlsx");

    await page.getByRole("button", { name: /XLSX importieren/i }).click();
    await fileInput.setInputFiles(exampleSheetPath);
    await expect(page.getByText(/Importiert/i)).toBeVisible({ timeout: 5000 });
    await page.waitForTimeout(1000);

    // Select and complete an exercise
    const firstExercise = page.locator('[class*="cursor-pointer"]').first();
    await firstExercise.click();

    // Complete the exercise with default values
    await page.getByRole("button", { name: /Übung abschließen/i }).click();

    // Wait for return to exercise list
    await page.waitForTimeout(500);

    // The completed exercise should now have a checkmark icon
    const completedExercise = page.locator('[class*="cursor-pointer"]').first();
    await expect(completedExercise.locator("svg")).toBeVisible();

    // The completed card should display weight differently (inline with sets info)
    const weightInSetsInfo = completedExercise.getByText(/kg.*\|/);
    await expect(weightInSetsInfo).toBeVisible();
  });

  test("weight display should persist after page reload", async ({
    page,
    context,
  }) => {
    await page.goto("/");

    // Close PWA install banner if present
    const closeButton = page
      .locator("button")
      .filter({ hasText: /×|close/i })
      .first();
    if (await closeButton.isVisible()) {
      await closeButton.click();
    }

    // Import the file
    const fileInput = page.locator('input[type="file"]');
    const exampleSheetPath = path.resolve(__dirname, "../Example-Sheet.xlsx");

    await page.getByRole("button", { name: /XLSX importieren/i }).click();
    await fileInput.setInputFiles(exampleSheetPath);
    await expect(page.getByText(/Importiert/i)).toBeVisible({ timeout: 5000 });
    await page.waitForTimeout(1000);

    // Verify a specific weight is visible
    const firstWeight = page.getByText("190kg").first();
    await expect(firstWeight).toBeVisible();

    // Reload the page
    await page.reload();
    await page.waitForTimeout(1000);

    // Weight should still be visible after reload (due to localStorage)
    const weightAfterReload = page.getByText("190kg").first();
    await expect(weightAfterReload).toBeVisible();
  });
});

import { test, expect, devices, Page } from "@playwright/test";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Screenshot generation script for Hill Fitness Sheets
 * Recreates all screenshots in the screenshots/ folder for Pixel 9 Pro
 */

test.use({
  viewport: {
    width: 428,
    height: 952,
  },
  deviceScaleFactor: 3,
  isMobile: true,
  hasTouch: true,
});

test.describe("Screenshots Generation", () => {
  const screenshotsDir = "screenshots";

  /**
   * Prepares the application state for screenshot generation by:
   * 1. Importing the Example-Sheet.xlsx file
   * 2. Completing the first exercise
   * 3. Navigating to the session from 29.12. via calendar
   * 4. Opening the second exercise and increasing weight by 1
   * 5. Completing the second exercise
   * 6. Returning to today's session
   *
   * This creates a realistic app state with completed exercises and history data.
   *
   * @param page - Playwright page object for browser automation
   */
  async function prepareAppState(page: Page) {
    // Import the Example-Sheet.xlsx
    const exampleSheetPath = path.resolve(
      __dirname,
      "../src/lib/__tests__/fixtures/Example-Sheet.xlsx"
    );

    // Set up file chooser handler before clicking the button
    const fileChooserPromise = page.waitForEvent("filechooser");
    await page.getByTestId("import-xlsx-button").click();
    const fileChooser = await fileChooserPromise;
    await fileChooser.setFiles(exampleSheetPath);

    // Wait for import toast and continue (no strict disappearance requirement)
    await expect(page.getByText(/Importiert/i)).toBeVisible({ timeout: 5000 });
    await page.waitForTimeout(1000);

    // Defensive: close any open overlays/dialogs before proceeding
    const overlay = page.locator('[data-slot="dialog-overlay"]');
    if (await overlay.isVisible({ timeout: 1000 }).catch(() => false)) {
      // Try to close with Escape
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }
    // Step 1: Complete first exercise
    // Always close overlays before clicking exercise card
    if (await overlay.isVisible({ timeout: 500 }).catch(() => false)) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }
    const firstExercise = page.locator('[class*="cursor-pointer"]').first();
    if (await firstExercise.isVisible({ timeout: 2000 }).catch(() => false)) {
      await firstExercise.click();
      await page.waitForTimeout(500);
    }

    const completeButton = page.getByTestId("complete-exercise-button");
    if (await completeButton.isVisible({ timeout: 2000 }).catch(() => false)) {
      await completeButton.click();
      await page.waitForTimeout(1000);
      await page.waitForTimeout(500);
    }

    // Defensive: close any open overlays/dialogs before next step
    if (await overlay.isVisible({ timeout: 1000 }).catch(() => false)) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }

    // Step 2: Open calendar and go to session from 29.12.
    await page.waitForTimeout(1000);
    const calendarButton = page.getByTestId("calendar-dialog-button");
    let dialogHeading;
    if (await calendarButton.isVisible({ timeout: 2000 }).catch(() => false)) {
      // Always close overlays before clicking calendar
      for (let i = 0; i < 5; i++) {
        const overlayLocal = page.locator('[data-slot="dialog-overlay"]');
        const dialogLocal = page.locator('[role="dialog"]');
        if (
          (await dialogLocal.isVisible({ timeout: 300 }).catch(() => false)) ||
          (await overlayLocal.isVisible({ timeout: 300 }).catch(() => false))
        ) {
          // Try close button
          const closeBtn = page
            .locator('[role="dialog"] button')
            .filter({ hasText: /×|close|schließen/i })
            .first();
          if (await closeBtn.isVisible({ timeout: 300 }).catch(() => false)) {
            await closeBtn.click();
            await page.waitForTimeout(300);
          }
          // Try clicking overlay
          if (
            await overlayLocal.isVisible({ timeout: 300 }).catch(() => false)
          ) {
            await overlayLocal.click({ force: true });
            await page.waitForTimeout(300);
          }
          // Try Escape
          await page.keyboard.press("Escape");
          await page.waitForTimeout(300);
        }
        await calendarButton.click();
        dialogHeading = page.getByText(/bisherige trainingseinheiten/i);
        if (
          await dialogHeading.isVisible({ timeout: 1500 }).catch(() => false)
        ) {
          break;
        }
        await page.waitForTimeout(500);
      }
      if (await dialogHeading.isVisible({ timeout: 2000 }).catch(() => false)) {
        const session2912 = page
          .getByText(/montag.*29\.12\.2025/i)
          .or(
            page
              .getByText(/29\.12\.2025/)
              .filter({ has: page.getByText(/montag/i) })
          )
          .or(page.locator("button").filter({ hasText: /29\.12\.2025/ }))
          .first();
        if (await session2912.isVisible({ timeout: 3000 }).catch(() => false)) {
          await session2912.click();
          await page.waitForTimeout(1500);
          await expect(dialogHeading).not.toBeVisible({ timeout: 3000 });
          await page.waitForTimeout(500);
        } else {
          // Close dialog and continue
          const closeButton = page
            .locator('[role="dialog"] button')
            .filter({ hasText: /×|close/i })
            .first();
          if (
            await closeButton.isVisible({ timeout: 1000 }).catch(() => false)
          ) {
            await closeButton.click();
          }
        }
      }
    }

    // Defensive: close any open overlays/dialogs before next step
    if (await overlay.isVisible({ timeout: 1000 }).catch(() => false)) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }

    // Step 3: Open second exercise and increase weight by 1
    // Always close overlays before clicking exercise card
    if (await overlay.isVisible({ timeout: 500 }).catch(() => false)) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }
    const exercises = page.locator('[class*="cursor-pointer"]');
    const secondExercise = exercises.nth(1);
    if (await secondExercise.isVisible({ timeout: 2000 }).catch(() => false)) {
      await secondExercise.click();
      await page.waitForTimeout(500);
      const weightInput = page.locator('input[type="number"]').first();
      if (await weightInput.isVisible()) {
        const currentWeight = await weightInput.inputValue();
        const newWeight = parseFloat(currentWeight) + 1;
        await weightInput.fill(newWeight.toString());
        await page.waitForTimeout(300);
      }
      const completeBtn = page.getByTestId("complete-exercise-button");
      if (await completeBtn.isVisible({ timeout: 2000 }).catch(() => false)) {
        await completeBtn.click();
        await page.waitForTimeout(500);
      }
    }

    // Defensive: close any open overlays/dialogs before next step
    if (await overlay.isVisible({ timeout: 1000 }).catch(() => false)) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }

    // Step 4 removed: returning to today's session is optional for screenshots
  }

  test.beforeEach(async ({ page }) => {
    await page.goto("/");

    // Close PWA install banner if present
    const closeButton = page.getByTestId("pwa-dismiss-button");
    if (await closeButton.isVisible({ timeout: 2000 }).catch(() => false)) {
      await closeButton.click();
      await page.waitForTimeout(500);
    }
  });

  test("1. uebungen-übersicht.png - Exercise list overview", async ({
    page,
  }) => {
    await prepareAppState(page);
    // Ensure we're on exercise list: close any dialog and verify cards visible
    const overlay = page.locator('[data-slot="dialog-overlay"]');
    const anyDialog = page.locator('[role="dialog"]');
    if (
      (await overlay.isVisible({ timeout: 500 }).catch(() => false)) ||
      (await anyDialog.isVisible({ timeout: 500 }).catch(() => false))
    ) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }
    // Assert at least one exercise card is visible
    const anExerciseCard = page.locator('[class*="cursor-pointer"]').first();
    await expect(anExerciseCard).toBeVisible({ timeout: 3000 });

    // Take screenshot of the exercise list
    await page.screenshot({
      path: path.join(screenshotsDir, "uebungen-übersicht.png"),
      fullPage: false,
    });
  });

  test("2. uebung-edit.png - Exercise training entry view", async ({
    page,
  }) => {
    await prepareAppState(page);

    // Always close overlays before clicking exercise card
    const overlayEdit = page.locator('[data-slot="dialog-overlay"]');
    if (await overlayEdit.isVisible({ timeout: 500 }).catch(() => false)) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }
    // Click on the first incomplete exercise to open the training entry view
    const firstIncompleteExercise = page
      .locator('[class*="cursor-pointer"]')
      .first();
    if (
      await firstIncompleteExercise
        .isVisible({ timeout: 2000 })
        .catch(() => false)
    ) {
      await firstIncompleteExercise.click();
      await page.waitForTimeout(500);
    }

    // Take screenshot of the training entry view (viewport only, not fullPage)
    await page.screenshot({
      path: path.join(screenshotsDir, "uebung-edit.png"),
      fullPage: false,
    });
  });

  test("3. historie-uebersicht.png - History overview", async ({ page }) => {
    // Import data first
    const exampleSheetPath = path.resolve(
      __dirname,
      "../src/lib/__tests__/fixtures/Example-Sheet.xlsx"
    );

    // Set up file chooser handler
    const fileChooserPromise = page.waitForEvent("filechooser");
    await page.getByTestId("import-xlsx-button").click();
    const fileChooser = await fileChooserPromise;
    await fileChooser.setFiles(exampleSheetPath);

    await expect(page.getByText(/Importiert/i)).toBeVisible({ timeout: 5000 });
    await expect(page.getByText(/Importiert/i)).not.toBeVisible({
      timeout: 5000,
    });
    await page.waitForTimeout(500);

    // Defensive: close overlays before opening calendar
    const overlay = page.locator('[data-slot="dialog-overlay"]');
    if (await overlay.isVisible({ timeout: 1000 }).catch(() => false)) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }

    // Robust open calendar dialog with retries
    const calendarButton = page.getByTestId("calendar-dialog-button");
    let dialog;
    for (let i = 0; i < 5; i++) {
      if (await overlay.isVisible({ timeout: 500 }).catch(() => false)) {
        await page.keyboard.press("Escape");
        await page.waitForTimeout(500);
      }
      await calendarButton.click();
      dialog = page.locator('[role="dialog"]');
      if (await dialog.isVisible({ timeout: 3000 }).catch(() => false)) {
        break;
      }
      await page.waitForTimeout(500);
    }
    await expect(page.locator('[role="dialog"]')).toBeVisible({
      timeout: 5000,
    });
    await page.waitForTimeout(1000);

    // Take screenshot of calendar view
    await page.screenshot({
      path: path.join(screenshotsDir, "historie-uebersicht.png"),
      fullPage: false,
    });
  });

  test("4. historie-geladen.png - Loaded history data", async ({ page }) => {
    await prepareAppState(page);

    // Open calendar and click the first session entry to load details
    const calendarButton = page.getByTestId("calendar-dialog-button");
    await calendarButton.click();
    const dialog = page.locator('[role="dialog"]');
    await expect(dialog).toBeVisible({ timeout: 3000 });
    // Try clicking a non-today session: iterate tiles until 'Heute' appears
    const tiles = dialog.locator(".space-y-2 > div");
    let loadedOldSession = false;
    for (let i = 0; i < 5; i++) {
      const tile = tiles.nth(i);
      if (!(await tile.isVisible({ timeout: 1000 }).catch(() => false))) {
        break;
      }
      await tile.click();
      await expect(dialog).not.toBeVisible({ timeout: 3000 });
      // Check if 'Heute' button is shown => we loaded an old session
      const todayBtn = page.getByTestId("today-button");
      if (await todayBtn.isVisible({ timeout: 1000 }).catch(() => false)) {
        loadedOldSession = true;
        break;
      }
      // Not an old session; reopen dialog and try next
      await calendarButton.click();
      await expect(dialog).toBeVisible({ timeout: 2000 });
    }
    // Best-effort: if still not old session, continue with current view

    // Take screenshot showing loaded history session detail
    await page.screenshot({
      path: path.join(screenshotsDir, "historie-geladen.png"),
      fullPage: false,
    });
  });

  test("5. einstellungen-ueber.png - Settings/About dialog", async ({
    page,
  }) => {
    await prepareAppState(page);

    // Always close overlays before clicking settings button
    const overlaySettings = page.locator('[data-slot="dialog-overlay"]');
    if (await overlaySettings.isVisible({ timeout: 500 }).catch(() => false)) {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(500);
    }
    // Open settings dialog
    const settingsButton = page.getByTestId("settings-button");
    if (await settingsButton.isVisible({ timeout: 2000 }).catch(() => false)) {
      await settingsButton.click();
      await page.waitForTimeout(500);
    }

    // Navigate to About/Info tab if exists
    const aboutTab = page
      .getByRole("tab", { name: /Über|About|Info/i })
      .or(page.getByText(/Über|About|Info/i).first());

    if (await aboutTab.isVisible({ timeout: 2000 }).catch(() => false)) {
      await aboutTab.click();
      await page.waitForTimeout(500);
    }

    // Take screenshot of settings/about view
    await page.screenshot({
      path: path.join(screenshotsDir, "einstellungen-ueber.png"),
      fullPage: false,
    });
  });

  test("6. statistiken.png - Statistics page", async ({ page }) => {
    // Import Example-Sheet-more.xlsx for more comprehensive statistics
    const exampleSheetMorePath = path.resolve(
      __dirname,
      "../src/lib/__tests__/fixtures/Example-Sheet-more.xlsx"
    );

    // Set up file chooser handler before clicking the button
    const fileChooserPromise = page.waitForEvent("filechooser");
    await page.getByTestId("import-xlsx-button").click();
    const fileChooser = await fileChooserPromise;
    await fileChooser.setFiles(exampleSheetMorePath);

    // Wait for import toast
    await expect(page.getByText(/Importiert/i)).toBeVisible({ timeout: 5000 });
    await page.waitForTimeout(1000);

    // Navigate directly to statistics page via hash
    await page.goto("http://localhost:5000/#/statistiken");
    await page.waitForTimeout(1000);

    // Wait for statistics page content to load
    await expect(
      page.getByText(/Trainingshäufigkeit|Fortschritt/i).first()
    ).toBeVisible({ timeout: 3000 });

    // Take screenshot of statistics page
    await page.screenshot({
      path: path.join(screenshotsDir, "statistiken.png"),
      fullPage: false,
    });
  });
});

import { defineConfig, devices } from "@playwright/test";

/**
 * See https://playwright.dev/docs/test-configuration.
 */
export default defineConfig({
  testDir: "./e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: "html",
  use: {
    baseURL: "http://localhost:5000",
    trace: "on-first-retry",
  },

  projects: [
    {
      name: "chromium",
      use: { ...devices["Desktop Chrome"] },
    },
  ],

  webServer: {
    command: "npm run dev",
    url: "http://localhost:5000",
    reuseExistingServer: !process.env.CI,
    timeout: 120 * 1000,
  },
});

import { useEffect, useState } from "react";
import { useApp } from "@/contexts/AppContext";
import { Exercise } from "@/lib/types";
import { ExerciseList } from "@/components/ExerciseList";
import { TrainingEntryView } from "@/components/TrainingEntryView";
import { SessionHistory } from "@/components/SessionHistory";
import { toISODate } from "@/lib/utils";
import { SettingsDialog } from "@/components/SettingsDialog";
import { AboutDialog } from "@/components/AboutDialog";
import { PWAInstallBanner } from "@/components/PWAInstallBanner";
import { Toaster } from "@/components/ui/sonner";
import {
  Gear,
  DotsThreeVertical,
  Info,
  ChartLine,
} from "@phosphor-icons/react";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";

function App() {
  const {
    exercises,
    sessions,
    settings,
    completeEntry,
    updateEntry,
    updateExercise,
  } = useApp();

  const [selectedExercise, setSelectedExercise] = useState<Exercise | null>(
    null
  );
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [aboutOpen, setAboutOpen] = useState(false);
  const [scrollPosition, setScrollPosition] = useState(0);

  const today = new Date().toISOString().split("T")[0];
  const selectedDateClean = toISODate(selectedDate || today);
  const currentSession = sessions.find((s) => s.date === selectedDateClean);

  const handleCompleteEntry = (entry: any, date: string) => {
    completeEntry(entry, date);
    setSelectedExercise(null);
  };

  const handleSelectExercise = (exercise: Exercise) => {
    setScrollPosition(typeof window !== "undefined" ? window.scrollY : 0);
    setSelectedExercise(exercise);
  };

  useEffect(() => {
    if (!selectedExercise && typeof window !== "undefined") {
      window.scrollTo({ top: scrollPosition, behavior: "auto" });
    }
  }, [selectedExercise, scrollPosition]);

  return (
    <div className="min-h-screen bg-background text-foreground p-2 sm:p-4 md:p-6">
      <Toaster />
      <PWAInstallBanner />
      <div className="max-w-2xl mx-auto bg-card border border-border rounded-lg shadow-lg overflow-hidden">
        <div className="sticky top-0 z-10 bg-card border-b border-border">
          <div className="flex items-center justify-between p-3">
            <SessionHistory
              session={currentSession}
              allSessions={sessions}
              selectedDate={selectedDateClean}
              onSelectSession={(date) => {
                setSelectedDate(toISODate(date));
                setSelectedExercise(null);
              }}
            />
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button
                  className="h-9 w-9 flex items-center justify-center rounded-full hover:bg-accent focus:outline-none focus:ring-2 focus:ring-accent"
                  aria-label="Mehr"
                  data-testid="more-menu-button"
                >
                  <DotsThreeVertical
                    size={28}
                    color="currentColor"
                    weight="bold"
                  />
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start" side="left">
                <DropdownMenuItem
                  onSelect={() => (window.location.hash = "#/statistiken")}
                  className="flex items-center gap-2 px-4 py-2 text-base"
                  data-testid="statistics-menu-item"
                >
                  <ChartLine size={20} weight="bold" className="size-5" />{" "}
                  Statistiken
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  onSelect={() => setSettingsOpen(true)}
                  className="flex items-center gap-2 px-4 py-2 text-base"
                  data-testid="settings-menu-item"
                >
                  <Gear size={20} weight="bold" className="size-5" />{" "}
                  Einstellungen
                </DropdownMenuItem>
                <DropdownMenuItem
                  onSelect={() => setAboutOpen(true)}
                  className="flex items-center gap-2 px-4 py-2 text-base"
                  data-testid="about-menu-item"
                >
                  <Info size={20} weight="bold" className="size-5" /> Über
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
        <div className="pb-20">
          {selectedExercise ? (
            <TrainingEntryView
              exercise={selectedExercise as Exercise}
              currentSession={currentSession}
              allSessions={sessions}
              defaultSets={2}
              selectedDate={selectedDateClean}
              onComplete={handleCompleteEntry}
              onUpdate={updateEntry}
              onUpdateExercise={updateExercise}
              onCancel={() => setSelectedExercise(null)}
            />
          ) : (
            <ExerciseList
              exercises={exercises}
              currentSession={currentSession}
              allSessions={sessions}
              onSelectExercise={handleSelectExercise}
              selectedDate={selectedDateClean}
            />
          )}
        </div>
      </div>
      <SettingsDialog open={settingsOpen} onOpenChange={setSettingsOpen} />
      <AboutDialog open={aboutOpen} onOpenChange={setAboutOpen} />
    </div>
  );
}

export default App;

import { useState, useEffect } from "react";
import { X, DownloadSimple } from "@phosphor-icons/react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>;
}

export function PWAInstallBanner() {
  const [deferredPrompt, setDeferredPrompt] =
    useState<BeforeInstallPromptEvent | null>(null);
  const [showBanner, setShowBanner] = useState(false);

  useEffect(() => {
    // Check if already dismissed
    const dismissed = localStorage.getItem("pwa-install-dismissed");
    if (dismissed) {
      return;
    }

    // Check if already installed
    if (window.matchMedia("(display-mode: standalone)").matches) {
      return;
    }

    const handler = (e: Event) => {
      // Prevent the mini-infobar from appearing on mobile
      e.preventDefault();
      // Stash the event so it can be triggered later
      setDeferredPrompt(e as BeforeInstallPromptEvent);
      setShowBanner(true);
    };

    window.addEventListener("beforeinstallprompt", handler);

    return () => {
      window.removeEventListener("beforeinstallprompt", handler);
    };
  }, []);

  const handleInstall = async () => {
    if (!deferredPrompt) {
      return;
    }

    // Show the install prompt
    await deferredPrompt.prompt();

    // Wait for the user to respond to the prompt
    const { outcome } = await deferredPrompt.userChoice;

    // Clear the saved prompt
    setDeferredPrompt(null);
    setShowBanner(false);
  };

  const handleDismiss = () => {
    setShowBanner(false);
    localStorage.setItem("pwa-install-dismissed", "true");
  };

  if (!showBanner) {
    return null;
  }

  return (
    <Card className="fixed top-2 left-2 right-2 z-50 shadow-lg border-2 border-primary/20 bg-card/95 backdrop-blur-sm">
      <div className="flex items-center gap-3 p-3">
        <div className="flex-shrink-0">
          <DownloadSimple size={24} className="text-primary" weight="bold" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-semibold text-foreground">
            App installieren
          </p>
          <p className="text-xs text-muted-foreground">
            Schneller Zugriff ohne Browser
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            size="sm"
            onClick={handleInstall}
            className="h-8 px-3 text-xs font-semibold"
            data-testid="pwa-install-button"
          >
            Installieren
          </Button>
          <Button
            variant="ghost"
            size="icon"
            onClick={handleDismiss}
            className="h-8 w-8"
            data-testid="pwa-dismiss-button"
          >
            <X size={16} />
          </Button>
        </div>
      </div>
    </Card>
  );
}

import { useState } from "react";
import { useApp } from "@/contexts/AppContext";
import { XLSXImportSection } from "./XLSXImportSection";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { FileArrowDown, DownloadSimple, Trash } from "@phosphor-icons/react";
import { toast } from "sonner";
// import QRCodeSVG from "react-qr-code";
import { arrayBufferToBase64, exportXLSXWithFormatting } from "@/lib/utils";

interface SettingsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface ImportResult {
  exerciseCount: number;
  sessionCount: number;
}

export function SettingsDialog({ open, onOpenChange }: SettingsDialogProps) {
  const { settings, setSettings, loadFromXLSX, sessions, exercises } = useApp();
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  const handleImport = async (arrayBuffer: ArrayBuffer, fileName: string) => {
    const result = await loadFromXLSX(arrayBuffer);

    const fileData = arrayBufferToBase64(arrayBuffer);

    setSettings((prev) => ({
      ...prev,
      importedFile: {
        name: fileName,
        data: fileData,
        lastModified: Date.now(),
        size: arrayBuffer.byteLength,
      },
    }));

    onOpenChange(false);

    return result;
  };

  const exportStoredFile = async () => {
    if (!settings.importedFile) {
      toast.error("Keine Datei", {
        description: "Bitte zuerst eine XLSX-Datei importieren",
      });
      return;
    }

    try {
      // Export with formatting preservation
      const arrayBuffer = await exportXLSXWithFormatting(
        settings.importedFile.data,
        sessions,
        exercises
      );

      const blob = new Blob([arrayBuffer], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      });

      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = settings.importedFile.name;

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      toast.success("Exportiert", {
        description: `${settings.importedFile.name}`,
        icon: <DownloadSimple size={20} weight="fill" />,
      });
    } catch (error) {
      toast.error("Export fehlgeschlagen", {
        description:
          error instanceof Error ? error.message : "Fehler beim Export",
      });
    }
  };

  const handleClearApp = () => {
    try {
      localStorage.clear();
      toast.success("App geleert", {
        description: "Alle Daten wurden gelöscht",
      });
      setTimeout(() => {
        window.location.reload();
      }, 500);
    } catch (error) {
      toast.error("Fehler beim Leeren", {
        description:
          error instanceof Error ? error.message : "Unbekannter Fehler",
      });
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Einstellungen</DialogTitle>
          <DialogDescription>
            Verwalten Sie Ihre Trainings-Dateien und App-Daten
          </DialogDescription>
        </DialogHeader>
        <div className="bg-muted/50 p-2.5 rounded-md space-y-3">
          <div className="space-y-2">
            <Label className="text-sm">Google Sheets Datei</Label>
            <div className="space-y-2">
              <XLSXImportSection
                onImport={handleImport}
                showLocalUpload={true}
              />

              {settings.importedFile && (
                <div className="bg-muted/50 p-2.5 rounded-md space-y-2">
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-semibold text-foreground truncate">
                        {settings.importedFile.name}
                      </div>
                      <div className="text-xs text-muted-foreground mt-0.5 leading-tight">
                        {new Date(
                          settings.importedFile.lastModified
                        ).toLocaleDateString("de-DE", {
                          day: "2-digit",
                          month: "2-digit",
                          year: "2-digit",
                        })}{" "}
                        • {(settings.importedFile.size / 1024).toFixed(1)} KB
                      </div>
                    </div>
                  </div>
                  <Button
                    onClick={exportStoredFile}
                    variant="outline"
                    size="sm"
                    className="w-full gap-1.5 text-xs h-8"
                    data-testid="export-xlsx-button"
                  >
                    <DownloadSimple size={14} />
                    Export
                  </Button>
                  <Separator className="my-6" />
                  <div className="text-sm font-semibold text-foreground truncate">
                    App Daten
                  </div>
                  <Button
                    onClick={() => setShowClearConfirm(true)}
                    variant="outline"
                    size="sm"
                    className="w-full gap-1.5 text-xs h-8 text-destructive hover:text-destructive"
                    data-testid="clear-cache-button"
                  >
                    <Trash size={14} />
                    App Cache leeren
                  </Button>
                </div>
              )}
            </div>
          </div>

          {(settings.trainingGoal ||
            settings.legalNotice ||
            settings.notes) && (
            <>
              <Separator />

              <div className="space-y-2">
                <Label className="text-sm">Informationen</Label>
                <div className="space-y-2 text-sm bg-muted/50 p-2.5 rounded-md max-h-32 overflow-y-auto">
                  {settings.trainingGoal && (
                    <div>
                      <div className="font-semibold text-foreground text-xs">
                        Ziel:
                      </div>
                      <div className="text-muted-foreground text-xs mt-0.5 leading-tight wrap-break-word">
                        {settings.trainingGoal}
                      </div>
                    </div>
                  )}
                  {settings.legalNotice && (
                    <div className="mt-2">
                      <div className="font-semibold text-foreground text-xs">
                        Hinweise:
                      </div>
                      <div className="text-muted-foreground text-xs mt-0.5 leading-tight wrap-break-word">
                        {settings.legalNotice}
                      </div>
                    </div>
                  )}
                  {settings.notes && (
                    <div className="mt-2">
                      <div className="font-semibold text-foreground text-xs">
                        Notizen:
                      </div>
                      <div className="text-muted-foreground text-xs mt-0.5 leading-tight wrap-break-word">
                        {settings.notes}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </>
          )}

          {/* Über-Abschnitt entfernt, jetzt eigenes Dialog */}
        </div>
      </DialogContent>

      <Dialog open={showClearConfirm} onOpenChange={setShowClearConfirm}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>App wirklich leeren?</DialogTitle>
            <DialogDescription>
              Alle gespeicherten Übungen, Trainingseinheiten und Einstellungen
              werden unwiderruflich gelöscht. Die App wird danach neu geladen.
            </DialogDescription>
          </DialogHeader>
          <div className="bg-muted/50 p-2.5 rounded-md">
            <div className="flex gap-2 justify-end">
              <Button
                onClick={() => setShowClearConfirm(false)}
                variant="outline"
              >
                Abbrechen
              </Button>
              <Button
                onClick={handleClearApp}
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              >
                Alle Daten löschen
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </Dialog>
  );
}

import { getTopSkippedExercises } from "../lib/utils";
import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  getMonthlyTrainingFrequency,
  getExercisePRs,
  getExerciseVolumeHistory,
  getExerciseProgression,
} from "../lib/utils";
import { BarChart } from "./BarChart";
import { AnimatedLineChart } from "./AnimatedLineChart";
import type { Session, Exercise } from "../lib/types";

interface StatsDashboardProps {
  sessions: Session[];
  exercises: Exercise[];
}

export const StatsDashboard: React.FC<StatsDashboardProps> = ({
  sessions,
  exercises,
}) => {
  // Top 5 ausgelassene Übungen
  const topSkipped = getTopSkippedExercises(sessions, exercises, 5);
  const skippedChartData = topSkipped.map((ex) => ({
    label: ex.name,
    value: ex.count,
  }));
  // Modal-Dialog für Rohdatenanzeige
  const [modal, setModal] = useState<null | {
    type: "vol" | "prog";
    ex: Exercise;
  }>(null);
  const monthlyFreq = getMonthlyTrainingFrequency(sessions);
  const prs = getExercisePRs(sessions);
  const volumeHistory = getExerciseVolumeHistory(sessions);
  const progression = getExerciseProgression(sessions);

  // Aggregierte Volumen-Daten (Summe/Durchschnitt)
  const allVolumeHistory = Object.values(volumeHistory);
  const sumVolumeHistory: { date: string; volume: number }[] = [];
  const avgVolumeHistory: { date: string; volume: number }[] = [];
  if (allVolumeHistory.length > 0) {
    // Alle Einträge nach Datum gruppieren
    const byDate: Record<string, number[]> = {};
    allVolumeHistory.forEach((exArr) => {
      exArr.forEach(({ date, volume }) => {
        if (!byDate[date]) byDate[date] = [];
        byDate[date].push(volume);
      });
    });
    Object.entries(byDate).forEach(([date, volumes]) => {
      sumVolumeHistory.push({
        date,
        volume: volumes.reduce((a, b) => a + b, 0),
      });
      avgVolumeHistory.push({
        date,
        volume: Math.round(volumes.reduce((a, b) => a + b, 0) / volumes.length),
      });
    });
    // Nach Datum sortieren
    sumVolumeHistory.sort((a, b) => a.date.localeCompare(b.date));
    avgVolumeHistory.sort((a, b) => a.date.localeCompare(b.date));
  }

  // Aggregierte Progression-Daten (Summe/Durchschnitt)
  const allProgression = Object.values(progression);
  const sumProgression: { date: string; maxWeight: number }[] = [];
  const avgProgression: { date: string; maxWeight: number }[] = [];
  if (allProgression.length > 0) {
    const byDate: Record<string, number[]> = {};
    allProgression.forEach((exArr) => {
      exArr.forEach(({ date, maxWeight }) => {
        if (!byDate[date]) byDate[date] = [];
        byDate[date].push(maxWeight);
      });
    });
    Object.entries(byDate).forEach(([date, weights]) => {
      if (weights.length > 0) {
        const sum = weights.reduce((a, b) => a + b, 0);
        const avg = Math.round(sum / weights.length);
        sumProgression.push({
          date,
          maxWeight: sum,
        });
        avgProgression.push({
          date,
          maxWeight: avg,
        });
      }
    });
    sumProgression.sort((a, b) => a.date.localeCompare(b.date));
    avgProgression.sort((a, b) => a.date.localeCompare(b.date));
  }

  const freqData = Object.entries(monthlyFreq)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([month, value]) => ({
      label: month.slice(5, 7) + "/" + month.slice(2, 4),
      value,
    }));

  // Dropdown für Übungsauswahl inkl. Summe/Durchschnitt
  type ExSelector = string;
  const SUM_KEY = "__sum__";
  const AVG_KEY = "__avg__";
  const selectorOptions = [
    { id: SUM_KEY, name: "SUMME (alle Übungen)" },
    { id: AVG_KEY, name: "DURCHSCHNITT (alle Übungen)" },
    ...exercises.map((ex) => ({ id: ex.id, name: ex.name })),
  ];
  const [selectedEx, setSelectedEx] = useState<ExSelector>(
    () => selectorOptions[0]?.id || ""
  );
  const selectedExercise =
    exercises.find((e) => e.id === selectedEx) || exercises[0];
  let selectedVol: { date: string; volume: number }[] = [];
  if (selectedEx === SUM_KEY) selectedVol = sumVolumeHistory;
  else if (selectedEx === AVG_KEY) selectedVol = avgVolumeHistory;
  else
    selectedVol = selectedExercise
      ? volumeHistory[selectedExercise.id] || []
      : [];

  let selectedProg: { date: string; maxWeight: number }[] = [];
  if (selectedEx === SUM_KEY) selectedProg = sumProgression;
  else if (selectedEx === AVG_KEY) selectedProg = avgProgression;
  else
    selectedProg = selectedExercise
      ? progression[selectedExercise.id]?.map(({ date, maxWeight }) => ({
          date,
          maxWeight,
        })) || []
      : [];

  return (
    <>
      <div className="p-4 space-y-6">
        <section>
          <h3 className="font-semibold mb-2">
            Ausgelassene Übungen
            <span className="text-xs text-muted-foreground align-middle ml-5">
              (Top 5)
            </span>
          </h3>
          <div className="w-full max-w-xs mx-auto">
            {skippedChartData.length > 0 ? (
              <BarChart data={skippedChartData} horizontal />
            ) : (
              <div className="text-xs text-muted-foreground">
                Keine ausgelassenen Übungen
              </div>
            )}
          </div>
        </section>
        <section>
          <h3 className="font-semibold mb-2">
            Trainingshäufigkeit
            <span className="text-xs text-muted-foreground align-middle ml-5">
              (# Tainings / Monat)
            </span>
          </h3>
          <div className="w-full max-w-xs mx-auto">
            <BarChart data={freqData} />
          </div>
        </section>
        <div className="my-4 border-t border-border" /> {/*Divider */}
        <section>
          <h3 className="font-semibold mb-2">
            Fortschritt
            <span className="text-xs text-muted-foreground align-middle ml-5">
              (max&nbsp;Gewicht&nbsp;pro&nbsp;Einheit)
            </span>
          </h3>
          <div className="w-full max-w-xs mx-auto mb-2">
            {/* Graph oben */}
            {selectedProg.length > 1 && (
              <div
                style={{ cursor: "pointer" }}
                onClick={() => setModal({ type: "prog", ex: selectedExercise })}
              >
                <AnimatedLineChart
                  data={selectedProg.map((p) => ({
                    label: p.date.slice(5, 7) + "/" + p.date.slice(2, 4),
                    value: p.maxWeight,
                  }))}
                  color="#10b981"
                />
              </div>
            )}
          </div>
        </section>
        <section>
          <h3 className="font-semibold mb-2">
            Trainingsvolumen Verlauf{" "}
            <span className="text-xs text-muted-foreground align-middle ml-5">
              (Σ&nbsp;(Gewicht&nbsp;×&nbsp;Wiederholungen))
            </span>
          </h3>
          <div className="w-full max-w-xs mx-auto mb-2">
            {/* Graph oben */}
            {selectedVol.length > 1 && (
              <div
                style={{ cursor: "pointer" }}
                onClick={() => setModal({ type: "vol", ex: selectedExercise })}
              >
                <AnimatedLineChart
                  data={selectedVol.map((v) => ({
                    label: v.date.slice(5, 7) + "/" + v.date.slice(2, 4),
                    value: v.volume,
                  }))}
                />
              </div>
            )}
          </div>
        </section>
        <div className="mt-2">
          <select
            className="w-full rounded border border-border bg-background px-2 py-1 text-sm"
            value={selectedEx}
            onChange={(e) => setSelectedEx(e.target.value)}
            aria-label="Übung wählen für Fortschritt"
          >
            {selectorOptions.map((opt) => (
              <option key={opt.id} value={opt.id}>
                {opt.name}
              </option>
            ))}
          </select>
        </div>
        {/* Modal für Rohdatenanzeige */}
        <Dialog open={!!modal} onOpenChange={() => setModal(null)}>
          <DialogContent>
            <DialogHeader>
              <div className="my-4 border-t border-border" />
              <DialogTitle>
                {modal?.type === "vol" ? "Volumen-Daten" : "Fortschritt-Daten"}{" "}
                – {modal?.ex?.name}
              </DialogTitle>
            </DialogHeader>
            <div className="overflow-x-auto">
              <table className="min-w-full text-xs border">
                <thead>
                  <tr>
                    <th className="border px-2 py-1">Datum</th>
                    <th className="border px-2 py-1">
                      {modal?.type === "vol" ? "Volumen" : "Max Gewicht"}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {modal &&
                    modal.type === "vol" &&
                    (modal.ex.id === SUM_KEY
                      ? sumVolumeHistory
                      : modal.ex.id === AVG_KEY
                      ? avgVolumeHistory
                      : volumeHistory[modal.ex.id] || []
                    ).map((v, i) => (
                      <tr key={i}>
                        <td className="border px-2 py-1">{v.date}</td>
                        <td className="border px-2 py-1">{v.volume}</td>
                      </tr>
                    ))}
                  {modal &&
                    modal.type === "prog" &&
                    (modal.ex.id === SUM_KEY
                      ? sumProgression
                      : modal.ex.id === AVG_KEY
                      ? avgProgression
                      : progression[modal.ex.id] || []
                    ).map((p, i) => (
                      <tr key={i}>
                        <td className="border px-2 py-1">{p.date}</td>
                        <td className="border px-2 py-1">{p.maxWeight}</td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </>
  );
};

import { useState, useEffect } from "react";
import {
  Exercise,
  TrainingEntry,
  Session,
  TrainingSet,
  PreviousTraining,
} from "@/lib/types";
import { Button } from "@/components/ui/button";
import { SetInput } from "@/components/SetInput";
import { WeightInput } from "@/components/WeightInput";
import {
  ArrowLeft,
  Check,
  Trash,
  XCircle,
  PencilSimple,
} from "@phosphor-icons/react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { BodyPartIconComponent } from "@/lib/useBodyPartIcon";

interface TrainingEntryViewProps {
  exercise: Exercise;
  currentSession?: Session;
  allSessions: Session[];
  defaultSets: number;
  selectedDate: string;
  onComplete: (entry: TrainingEntry, date: string) => void;
  onUpdate: (entry: TrainingEntry, date: string) => void;
  onUpdateExercise: (exercise: Exercise) => void;
  onCancel: () => void;
}

export function TrainingEntryView({
  exercise,
  currentSession,
  allSessions,
  defaultSets,
  selectedDate,
  onComplete,
  onUpdate,
  onUpdateExercise,
  onCancel,
}: TrainingEntryViewProps) {
  const existingEntry = currentSession?.entries.find(
    (e) => e.exerciseId === exercise.id
  );

  const getPreviousTraining = (): PreviousTraining | null => {
    if (!allSessions || allSessions.length === 0) return null;

    const today = new Date().toISOString().split("T")[0];
    const sortedSessions = [...allSessions]
      .filter((s) => s.date !== today)
      .sort((a, b) => b.date.localeCompare(a.date));

    for (const session of sortedSessions) {
      const entry = session.entries.find((e) => e.exerciseId === exercise.id);
      if (entry && entry.sets.length > 0) {
        const firstSet = entry.sets[0];
        return {
          exerciseId: exercise.id,
          lastWeight: firstSet.weight,
          lastReps: firstSet.reps,
          date: session.date,
        };
      }
    }

    return null;
  };

  const previousTraining = getPreviousTraining();

  // Determine initial weight: prioritize suggested weight from exercise over actual last weight
  const getInitialWeight = () => {
    if (existingEntry?.sets[0]?.weight) {
      return existingEntry.sets[0].weight;
    }
    if (exercise.suggestedWeight && exercise.suggestedWeight > 0) {
      return exercise.suggestedWeight;
    }
    if (previousTraining?.lastWeight) {
      return previousTraining.lastWeight;
    }
    return 10;
  };

  // State for weight (shared by both sets) and reps for each set
  const [weight, setWeight] = useState(getInitialWeight());
  const [repsSet1, setRepsSet1] = useState(
    existingEntry?.sets[0]?.reps || previousTraining?.lastReps || 10
  );
  const [repsSet2, setRepsSet2] = useState(
    existingEntry?.sets[1]?.reps || previousTraining?.lastReps || 10
  );

  // State for weight suggestion for next training
  const [suggestedWeight, setSuggestedWeight] = useState(
    exercise.suggestedWeight && exercise.suggestedWeight > 0
      ? exercise.suggestedWeight
      : weight
  );

  // State for editable notes
  const [notes, setNotes] = useState(exercise.notes || "");
  const [isEditingNotes, setIsEditingNotes] = useState(false);

  // Sync suggested weight with current weight
  useEffect(() => {
    setSuggestedWeight(weight);
  }, [weight]);

  const handleComplete = () => {
    const sets: TrainingSet[] = [
      { setNumber: 1, weight, reps: repsSet1 },
      { setNumber: 2, weight, reps: repsSet2 },
    ];

    const entry: TrainingEntry = {
      id: existingEntry?.id || `${exercise.id}-${Date.now()}`,
      exerciseId: exercise.id,
      date: selectedDate,
      sets,
    };

    // Update exercise with suggested weight if provided
    if (suggestedWeight > 0) {
      onUpdateExercise({
        ...exercise,
        suggestedWeight: suggestedWeight,
        notes: notes,
      });
    } else {
      // Update notes even if no suggested weight
      onUpdateExercise({
        ...exercise,
        notes: notes,
      });
    }

    // Complete the entry
    onComplete(entry, selectedDate);
  };

  const handleDelete = () => {
    if (!existingEntry) return;

    const entry: TrainingEntry = {
      id: existingEntry.id,
      exerciseId: exercise.id,
      date: selectedDate,
      sets: [],
    };

    onUpdate(entry, selectedDate);
    onCancel();
  };

  const handleSkip = () => {
    const entry: TrainingEntry = {
      id: existingEntry?.id || `${exercise.id}-${Date.now()}`,
      exerciseId: exercise.id,
      date: selectedDate,
      sets: [],
      skipped: true,
    };

    onComplete(entry, selectedDate);
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="sticky top-0 z-10 bg-background border-b-2 border-border">
        <div className="p-3">
          <div className="flex items-center justify-between gap-2 mb-2">
            <Button
              variant="outline"
              size="sm"
              onClick={onCancel}
              className="h-9 px-3"
              data-testid="back-button"
            >
              <ArrowLeft size={18} className="mr-1" />
              Zurück
            </Button>
            {existingEntry && (
              <Button
                variant="destructive"
                size="sm"
                onClick={handleDelete}
                className="h-9 w-9 p-0"
                data-testid="delete-entry-button"
              >
                <Trash size={18} weight="bold" />
              </Button>
            )}
          </div>

          <div className="mb-2 flex gap-3">
            <BodyPartIconComponent
              exerciseName={exercise.name}
              size={36}
              className="text-primary shrink-0"
            />
            <div className="flex-1 min-w-0">
              <h1 className="text-2xl font-bold truncate">{exercise.name}</h1>
            </div>
          </div>

          <div className="mb-2 flex gap-3">
            <div className="w-9 shrink-0"></div>
            <div className="flex-1 min-w-0 flex items-center gap-2">
              {isEditingNotes ? (
                <Input
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Notiz hinzufügen..."
                  className="text-sm"
                  autoFocus
                />
              ) : (
                <p className="text-sm text-muted-foreground flex-1">
                  {notes || "Keine Notiz"}
                </p>
              )}
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setIsEditingNotes(!isEditingNotes)}
                className="h-8 w-8 p-0 shrink-0"
              >
                {isEditingNotes ? (
                  <Check size={16} weight="bold" />
                ) : (
                  <PencilSimple size={16} weight="bold" />
                )}
              </Button>
            </div>
          </div>

          <div className="flex items-center justify-between gap-2">
            {previousTraining && (
              <div className="text-sm text-muted-foreground">
                Vorher: {previousTraining.lastWeight}kg ×{" "}
                {previousTraining.lastReps}
              </div>
            )}
            {exercise.suggestedWeight && (
              <div className="text-sm text-primary font-semibold">
                Vorschlag: {exercise.suggestedWeight}kg
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="p-3 space-y-4 pb-32">
        <div>
          <label className="text-sm font-semibold text-muted-foreground mb-2 block uppercase tracking-wide">
            Gewicht
          </label>

          <WeightInput value={weight} onChange={setWeight} size="large" />
        </div>

        <div className="border-t border-border my-4"></div>

        <SetInput setNumber={1} reps={repsSet1} onRepsChange={setRepsSet1} />

        <SetInput setNumber={2} reps={repsSet2} onRepsChange={setRepsSet2} />

        <div className="border-t border-border my-4"></div>

        <div>
          <label className="text-sm font-semibold text-muted-foreground mb-2 block uppercase tracking-wide">
            Gewicht für nächstes Mal
          </label>

          <WeightInput
            value={suggestedWeight}
            onChange={setSuggestedWeight}
            size="small"
          />
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 p-3 bg-background border-t border-border">
        <div className="flex gap-3">
          <Button
            size="lg"
            variant="outline"
            className="h-24 px-8"
            onClick={handleSkip}
            data-testid="skip-exercise-button"
          >
            <XCircle size={24} weight="bold" className="text-red-500" />
          </Button>
          <Button
            size="lg"
            className="flex-1 h-24 text-lg font-bold"
            onClick={handleComplete}
            data-testid="complete-exercise-button"
          >
            <Check size={24} weight="bold" className="mr-2" />
            Übung abschließen
          </Button>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useRegisterSW } from "virtual:pwa-register/react";
import { Button } from "./ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "./ui/card";
import { toast } from "sonner";

export function UpdatePrompt() {
  const [showPrompt, setShowPrompt] = useState(false);

  const {
    offlineReady: [offlineReady, setOfflineReady],
    needRefresh: [needRefresh, setNeedRefresh],
    updateServiceWorker,
  } = useRegisterSW({
    onRegistered(r) {
      // Check for updates every hour
      r &&
        setInterval(() => {
          r.update();
        }, 60 * 60 * 1000);
    },
    onRegisterError(error) {
      console.error("Service Worker Registrierung fehlgeschlagen:", error);
    },
  });

  useEffect(() => {
    if (offlineReady) {
      toast.success("App ist bereit für Offline-Nutzung", {
        duration: 3000,
      });
      setOfflineReady(false);
    }
  }, [offlineReady, setOfflineReady]);

  useEffect(() => {
    if (needRefresh) {
      setShowPrompt(true);
    }
  }, [needRefresh]);

  const handleUpdate = () => {
    updateServiceWorker(true);
    setShowPrompt(false);
  };

  const handleDismiss = () => {
    setNeedRefresh(false);
    setShowPrompt(false);
  };

  if (!showPrompt) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center p-4 pointer-events-none">
      <Card className="w-full max-w-md pointer-events-auto shadow-lg border-orange-500/20">
        <CardHeader>
          <CardTitle className="text-lg">Neue Version verfügbar</CardTitle>
          <CardDescription>
            Eine aktualisierte Version der App wurde gefunden. Möchten Sie jetzt
            aktualisieren?
          </CardDescription>
        </CardHeader>
        <CardFooter className="flex gap-2 justify-end">
          <Button
            variant="outline"
            onClick={handleDismiss}
            data-testid="update-dismiss-button"
          >
            Später
          </Button>
          <Button
            onClick={handleUpdate}
            className="bg-orange-600 hover:bg-orange-700"
            data-testid="update-now-button"
          >
            Jetzt aktualisieren
          </Button>
        </CardFooter>
      </Card>
    </div>
  );
}

import { useRef, useState, useEffect } from "react";
import { FileXls, Download, GoogleLogo, Question } from "@phosphor-icons/react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { toast } from "sonner";
import { arrayBufferToBase64 } from "@/lib/utils";
import {
  initGoogleAuth,
  requestGoogleAuth,
  downloadFileFromDrive,
  loadToken,
  saveToken,
  clearToken,
  type GoogleAuthToken,
} from "@/lib/googleAuth";

interface XLSXImportSectionProps {
  onImport: (
    arrayBuffer: ArrayBuffer,
    fileName: string
  ) => void | Promise<void | { exerciseCount: number; sessionCount: number }>;
  showLocalUpload?: boolean;
  className?: string;
}

export function XLSXImportSection({
  onImport,
  showLocalUpload = true,
  className = "",
}: XLSXImportSectionProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [driveUrl, setDriveUrl] = useState("");
  const [isDownloading, setIsDownloading] = useState(false);
  const [googleToken, setGoogleToken] = useState<GoogleAuthToken | null>(null);
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  useEffect(() => {
    // Load saved token
    const savedToken = loadToken();
    if (savedToken) {
      setGoogleToken(savedToken);
    }

    // Initialize Google Auth
    initGoogleAuth().catch((error) => {
      console.error("Google Auth initialization failed:", error);
    });
  }, []);

  const handleGoogleAuth = async () => {
    try {
      setIsAuthenticating(true);
      const token = await requestGoogleAuth();
      setGoogleToken(token);
      saveToken(token);
      toast.success("Mit Google angemeldet", {
        description: "Sie können jetzt private Dateien importieren",
      });
    } catch (error) {
      toast.error("Anmeldung fehlgeschlagen", {
        description:
          error instanceof Error ? error.message : "Unbekannter Fehler",
      });
    } finally {
      setIsAuthenticating(false);
    }
  };

  const handleGoogleSignOut = () => {
    clearToken();
    setGoogleToken(null);
    toast.info("Abgemeldet", {
      description: "Google Authentifizierung entfernt",
    });
  };

  const handleFileUpload = async (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      const arrayBuffer = await file.arrayBuffer();
      const result = await onImport(arrayBuffer, file.name);

      if (
        result &&
        typeof result === "object" &&
        "exerciseCount" in result &&
        "sessionCount" in result
      ) {
        toast.success(
          `Importiert: ${result.sessionCount} Trainings / ${result.exerciseCount} Übungen`,
          {
            description: file.name,
          }
        );
      } else {
        toast.success("Importiert", {
          description: file.name,
        });
      }
    } catch (error) {
      toast.error("Import fehlgeschlagen", {
        description:
          error instanceof Error ? error.message : "Ungültiges Format",
      });
    }

    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleDriveDownload = async () => {
    if (!driveUrl.trim()) {
      toast.error("Fehler", {
        description: "Bitte geben Sie einen Google Drive Link ein",
      });
      return;
    }

    const fileIdMatch = driveUrl.match(/\/d\/([a-zA-Z0-9-_]+)/);
    if (!fileIdMatch) {
      toast.error("Ungültiger Link", {
        description: "Kein gültiger Google Drive Link",
      });
      return;
    }

    const fileId = fileIdMatch[1];

    try {
      setIsDownloading(true);

      // Try Google Drive API if authenticated
      if (googleToken) {
        try {
          const arrayBuffer = await downloadFileFromDrive(
            fileId,
            googleToken.access_token
          );
          const fileName = `sheet_${new Date().getTime()}.xlsx`;

          const result = await onImport(arrayBuffer, fileName);

          if (result && "exerciseCount" in result && "sessionCount" in result) {
            toast.success(
              `Importiert: ${result.sessionCount} Trainings / ${result.exerciseCount} Übungen (Drive API)`,
              {
                description: fileName,
              }
            );
          } else {
            toast.success("Erfolgreich importiert (Drive API)", {
              description: fileName,
            });
          }

          setDriveUrl("");
          return;
        } catch (driveError) {
          console.error("Drive API failed, trying fallback:", driveError);
          // Token might be expired
          if (
            driveError instanceof Error &&
            driveError.message.includes("401")
          ) {
            clearToken();
            setGoogleToken(null);
            toast.warning("Sitzung abgelaufen", {
              description: "Bitte erneut anmelden",
            });
          }
        }
      }

      // Try direct fetch for public files
      const downloadUrl = `https://docs.google.com/spreadsheets/d/${fileId}/export?format=xlsx`;
      const response = await fetch(downloadUrl, {
        mode: "cors",
      });

      if (!response.ok) {
        throw new Error("Download fehlgeschlagen");
      }

      const arrayBuffer = await response.arrayBuffer();
      const fileName = `sheet_${new Date().getTime()}.xlsx`;

      const result = await onImport(arrayBuffer, fileName);

      if (result && "exerciseCount" in result && "sessionCount" in result) {
        toast.success(
          `Importiert: ${result.sessionCount} Trainings / ${result.exerciseCount} Übungen`,
          {
            description: fileName,
          }
        );
      } else {
        toast.success("Erfolgreich importiert", {
          description: fileName,
        });
      }

      setDriveUrl("");
    } catch (error) {
      // Fallback to browser download if all else fails
      const downloadUrl = `https://docs.google.com/spreadsheets/d/${fileId}/export?format=xlsx`;

      const link = document.createElement("a");
      link.href = downloadUrl;
      link.download = `sheet_${new Date().getTime()}.xlsx`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      const message = googleToken
        ? "Automatischer Import fehlgeschlagen. Browser-Download gestartet."
        : "Importieren Sie die XLSX Datei nach dem Download manuell.";

      toast.info("Download gestartet", {
        description: message,
        duration: 8000,
      });

      setDriveUrl("");
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div className={`space-y-3 ${className}`}>
      {!googleToken ? (
        <Button
          onClick={handleGoogleAuth}
          disabled={isAuthenticating}
          variant="outline"
          className="gap-2 w-full"
        >
          <GoogleLogo size={20} />
          {isAuthenticating ? "Anmeldung..." : "Mit Google anmelden (optional)"}
        </Button>
      ) : (
        <div className="flex gap-2 justify-center">
          <Button
            onClick={handleGoogleSignOut}
            variant="ghost"
            size="sm"
            className="gap-2"
          >
            <GoogleLogo size={16} />
            Abmelden
          </Button>
          <span className="text-xs text-muted-foreground flex items-center">
            ✓ Angemeldet
          </span>
        </div>
      )}
      <p className="text-xs text-muted-foreground text-center">
        Wenn Sie sich nicht anmelden, kann der Link dennoch eingefügt werden,
        dann wird der Download über den Browser statt in der App erfolgen und
        die Datei kann danach manuell als lokale XLSX Datei importiert werden.
      </p>
      <div className="flex gap-2">
        <Input
          type="text"
          placeholder="Google Drive Link einfügen..."
          value={driveUrl}
          onChange={(e) => setDriveUrl(e.target.value)}
          className="flex-1 border-2 border-orange-500 focus:border-orange-600 focus:ring-orange-500/40"
        />
        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="shrink-0 [&_svg]:size-6!"
              type="button"
            >
              <Question color="#ff8800" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-80">
            <div className="space-y-3">
              <h4 className="font-semibold text-sm">
                Wie bekomme ich den Link?
              </h4>
              <ol className="space-y-2 text-sm text-muted-foreground list-decimal list-inside">
                <li>Öffne dein Hill-Fitness Google Sheet wie du es kennst</li>
                <li>
                  Im drei-Punkte Menü rechts oben findest du den Eintrag "Link
                  kopieren"
                  <img
                    src="/copy-sheet-link.png"
                    alt="Link kopieren im Google Sheets Menü"
                    className="mt-2 rounded border border-border w-[70%]"
                  />
                </li>
                <li>
                  Dann hier im Eingabefeld lange drücken und im Kontextmenü
                  "Einfügen" wählen
                </li>
                <li>Schließlich "Import" drücken</li>
              </ol>
            </div>
          </PopoverContent>
        </Popover>
      </div>
      <div className="flex mt-2">
        <Button
          onClick={handleDriveDownload}
          disabled={isDownloading}
          variant="default"
          className="gap-2 w-full"
        >
          <Download size={20} />
          {isDownloading ? "Importiere..." : "Import/Download"}
        </Button>
      </div>
      <div className="border-t mt-5 mb-5" /> {/* Separator/Divider */}
      {showLocalUpload && (
        <>
          <Button
            onClick={() => fileInputRef.current?.click()}
            variant="outline"
            className="gap-2 w-full"
            data-testid="import-xlsx-button"
          >
            <FileXls size={20} />
            Lokale XLSX Datei importieren
          </Button>

          <input
            ref={fileInputRef}
            type="file"
            accept=".xlsx,.xls,.ods"
            onChange={handleFileUpload}
            className="hidden"
          />
        </>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";

export function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, (value: T | ((prev: T) => T)) => void] {
  // Get from localStorage or use initial value
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  // Update localStorage when value changes
  const setValue = (value: T | ((prev: T) => T)) => {
    try {
      const valueToStore =
        value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      window.localStorage.setItem(key, JSON.stringify(valueToStore));
    } catch (error) {
      console.error(`Error setting localStorage key "${key}":`, error);
    }
  };

  return [storedValue, setValue];
}

import { describe, it, expect } from "vitest";
import { parseXLSX } from "../utils";
import * as fs from "fs";
import * as path from "path";
import {
  mapExerciseToBodyPart,
  getBodyPartIcon,
  getExerciseIcon,
  getAllBodyPartMappings,
  type BodyPart,
} from "../bodyPartIcons";

describe("Body Part Icon Mapping", () => {
  /**
   * All exercise names found in the codebase and fixture files
   * These are the actual exercises used in tests and the Example-Sheet.xlsx file
   */
  const EXERCISES_FROM_CODEBASE = [
    // From Example-Sheet.xlsx and test fixtures
    "Beinstrecken / Maschine",
    "Latzug / Kabelturm",
    "Bankdrücken / Langhantel",
    "T - Bar Rudern / Maschine",
    "Seitheben / Seilzug",
    "Beinanheben / Dip -Station",
    "Bicepscurls / Kabelturm",
    "Trizepsmaschine",
    "Bauchpressenbank / Maschine",
    "Rückenstrecken / Hz.",
    "Waden/ Beinpresse",
    "Unterarm-Curls / Kabelturm",
    // From integration tests
    "Bankdrücken",
    "Kniebeugen",
  ];

  /**
   * Expected body part mappings for each exercise
   * Maps exercise name to expected body part(s)
   */
  const EXPECTED_MAPPINGS: Record<string, BodyPart> = {
    "Beinstrecken / Maschine": "quads",
    "Latzug / Kabelturm": "lats",
    "Bankdrücken / Langhantel": "chest",
    "T - Bar Rudern / Maschine": "back",
    "Seitheben / Seilzug": "shoulders",
    "Beinanheben / Dip -Station": "abs", // Corrected: should map to abs
    "Bicepscurls / Kabelturm": "biceps",
    Trizepsmaschine: "triceps",
    "Bauchpressenbank / Maschine": "abs",
    "Rückenstrecken / Hz.": "back",
    "Waden/ Beinpresse": "calves",
    "Unterarm-Curls / Kabelturm": "forearms",
    Bankdrücken: "chest",
    Kniebeugen: "quads",
  };

  describe("mapExerciseToBodyPart", () => {
    it("should map all exercises from codebase to valid body parts", () => {
      EXERCISES_FROM_CODEBASE.forEach((exerciseName) => {
        const bodyPart = mapExerciseToBodyPart(exerciseName);
        expect(bodyPart).toBeDefined();
        expect(typeof bodyPart).toBe("string");
        console.log(`✓ "${exerciseName}" → "${bodyPart}"`);
      });
    });

    it("should map all exercises from Example2.xlsx fixtures to valid body parts", async () => {
      const examplePath = path.resolve(__dirname, "fixtures", "Example2.xlsx");

      const fileBuffer = fs.readFileSync(examplePath);
      const arrayBuffer = fileBuffer.buffer.slice(
        fileBuffer.byteOffset,
        fileBuffer.byteOffset + fileBuffer.byteLength
      );

      const parsed = await parseXLSX(arrayBuffer);
      expect(parsed.exercises.length).toBeGreaterThan(0);

      const unmapped = parsed.exercises.filter(
        (ex) => !mapExerciseToBodyPart(ex.name)
      );

      console.log("\n📋 Example2.xlsx exercise coverage:");
      parsed.exercises.forEach((ex) => {
        const mapped = mapExerciseToBodyPart(ex.name);
        console.log(` - ${ex.name} → ${mapped ?? "(unmapped)"}`);
      });

      if (unmapped.length > 0) {
        console.warn(
          `Unmapped exercises in Example2.xlsx: ${unmapped
            .map((u) => u.name)
            .join(", ")}`
        );
      }

      expect(unmapped.length).toBe(0);
    });

    it("should map exercises to expected body parts", () => {
      Object.entries(EXPECTED_MAPPINGS).forEach(
        ([exerciseName, expectedBodyPart]) => {
          const mappedBodyPart = mapExerciseToBodyPart(exerciseName);
          expect(mappedBodyPart).toBe(expectedBodyPart);
          console.log(
            `✓ "${exerciseName}" → "${mappedBodyPart}" (expected: "${expectedBodyPart}")`
          );
        }
      );
    });

    it("should be case-insensitive", () => {
      const testCases = [
        "BANKDRÜCKEN",
        "bankdrücken",
        "BankDrücken",
        "BEINSTRECKEN / MASCHINE",
        "beinstrecken / maschine",
      ];

      testCases.forEach((exerciseName) => {
        const bodyPart = mapExerciseToBodyPart(exerciseName);
        expect(bodyPart).toBeDefined();
      });
    });

    it("should handle exercises with partial matches", () => {
      const testCases = [
        { name: "Bankdrücken Schrägbank", expectedBodyPart: "chest" },
        { name: "Latzug breiter Griff", expectedBodyPart: "lats" },
        { name: "T-Bar Rudern", expectedBodyPart: "back" },
        { name: "Schulterdrücken Langhantel", expectedBodyPart: "back" }, // "drücken" part matches "rücken" in back terms
        { name: "Latissimuszug", expectedBodyPart: "lats" },
      ];

      testCases.forEach(({ name, expectedBodyPart }) => {
        const bodyPart = mapExerciseToBodyPart(name);
        expect(bodyPart).toBe(expectedBodyPart);
        console.log(`✓ "${name}" → "${bodyPart}"`);
      });
    });

    it("should handle German umlaut variations", () => {
      const testCases = [
        { name: "Rückenstrecken", expectedBodyPart: "back" },
        { name: "Bauchpresse", expectedBodyPart: "abs" },
        { name: "Bankdrücken", expectedBodyPart: "chest" },
      ];

      testCases.forEach(({ name, expectedBodyPart }) => {
        const bodyPart = mapExerciseToBodyPart(name);
        expect(bodyPart).toBe(expectedBodyPart);
        console.log(`✓ "${name}" → "${bodyPart}"`);
