function countColoredCells(workbook: ExcelJS.Workbook): number {
  let count = 0;
  for (const sheet of workbook.worksheets) {
    sheet.eachRow((row) => {
      row.eachCell((cell) => {
        if (
          cell.fill &&
          (cell.fill.bgColor ||
            cell.fill.fgColor ||
            cell.fill.pattern ||
            cell.fill.type !== "none")
        ) {
          count++;
        }
      });
    });
  }
  return count;
}

