// Google OAuth and Drive API integration

const GOOGLE_CLIENT_ID = import.meta.env.VITE_GOOGLE_CLIENT_ID;
const SCOPES = "https://www.googleapis.com/auth/drive.file";

export interface GoogleAuthToken {
  access_token: string;
  expires_in: number;
  token_type: string;
  scope: string;
  expires_at: number;
}

let tokenClient: google.accounts.oauth2.TokenClient | null = null;

export function initGoogleAuth(): Promise<void> {
  return new Promise((resolve, reject) => {
    if (!GOOGLE_CLIENT_ID) {
      reject(new Error("VITE_GOOGLE_CLIENT_ID nicht konfiguriert"));
      return;
    }

    if (typeof google === "undefined" || !google.accounts) {
      // Load Google Identity Services script
      const script = document.createElement("script");
      script.src = "https://accounts.google.com/gsi/client";
      script.async = true;
      script.defer = true;
      script.onload = () => resolve();
      script.onerror = () =>
        reject(new Error("Google Auth Script konnte nicht geladen werden"));
      document.head.appendChild(script);
    } else {
      resolve();
    }
  });
}

export function requestGoogleAuth(): Promise<GoogleAuthToken> {
  return new Promise((resolve, reject) => {
    if (!GOOGLE_CLIENT_ID) {
      reject(new Error("VITE_GOOGLE_CLIENT_ID nicht konfiguriert"));
      return;
    }

    try {
      tokenClient = google.accounts.oauth2.initTokenClient({
        client_id: GOOGLE_CLIENT_ID,
        scope: SCOPES,
        callback: (response: google.accounts.oauth2.TokenResponse) => {
          if (response.error) {
            reject(new Error(response.error));
            return;
          }

          const token: GoogleAuthToken = {
            access_token: response.access_token,
            expires_in: parseInt(response.expires_in || "3600"),
            token_type: response.token_type || "Bearer",
            scope: response.scope || SCOPES,
            expires_at:
              Date.now() + parseInt(response.expires_in || "3600") * 1000,
          };

          resolve(token);
        },
      });

      tokenClient.requestAccessToken({ prompt: "consent" });
    } catch (error) {
      reject(error);
    }
  });
}

export async function downloadFileFromDrive(
  fileId: string,
  accessToken: string
): Promise<ArrayBuffer> {
  // First, get file metadata to determine if it's a Google Sheets file or uploaded file
  const metadataUrl = `https://www.googleapis.com/drive/v3/files/${fileId}?fields=mimeType`;

  const metadataResponse = await fetch(metadataUrl, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
    },
  });

  if (!metadataResponse.ok) {
    throw new Error(
      `Drive API Fehler: ${metadataResponse.status} ${metadataResponse.statusText}`
    );
  }

  const metadata = await metadataResponse.json();
  const mimeType = metadata.mimeType;

  let url: string;

  // Check if it's a Google Sheets file or an uploaded file
  if (mimeType === "application/vnd.google-apps.spreadsheet") {
    // Native Google Sheets - use export endpoint
    url = `https://www.googleapis.com/drive/v3/files/${fileId}/export?mimeType=application/vnd.openxmlformats-officedocument.spreadsheetml.sheet`;
  } else {
    // Uploaded file (e.g., .xlsx) - use direct download
    url = `https://www.googleapis.com/drive/v3/files/${fileId}?alt=media`;
  }

  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
    },
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Drive API Fehler: ${response.status} - ${errorText}`);
  }

  return response.arrayBuffer();
}

export function saveToken(token: GoogleAuthToken): void {
  localStorage.setItem("google_auth_token", JSON.stringify(token));
}

export function loadToken(): GoogleAuthToken | null {
  const tokenStr = localStorage.getItem("google_auth_token");
  if (!tokenStr) return null;

  try {
    const token = JSON.parse(tokenStr) as GoogleAuthToken;
    // Check if token is expired
    if (token.expires_at && token.expires_at < Date.now()) {
      localStorage.removeItem("google_auth_token");
      return null;
    }
    return token;
  } catch {
    return null;
  }
}

export function clearToken(): void {
  localStorage.removeItem("google_auth_token");
}

// Type declarations for Google Identity Services
declare global {
  interface Window {
    google?: typeof google;
  }

  namespace google {
    namespace accounts {
      namespace oauth2 {
        interface TokenClient {
          requestAccessToken(options?: { prompt?: string }): void;
        }

        interface TokenResponse {
          access_token: string;
          expires_in?: string;
          token_type?: string;
          scope?: string;
          error?: string;
          error_description?: string;
        }

        function initTokenClient(config: {
          client_id: string;
          scope: string;
          callback: (response: TokenResponse) => void;
        }): TokenClient;
      }
    }
  }
}

﻿import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import { Exercise, Session, TrainingEntry } from "./types";

// Re-exports from specialized XLSX modules
export { parseXLSX } from "./xlsxImport";
export { updateXLSXWithSessions, exportXLSXWithFormatting } from "./xlsxExport";

// Utility function: combine class names with Tailwind merge
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Normalize various date string formats to ISO YYYY-MM-DD
export function toISODate(dateString: string): string {
  if (!dateString) return "";
  const trimmed = dateString.replace(" ?", "").trim();
  // Already ISO
  if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return trimmed;
  // German format DD.MM.YYYY
  const deMatch = trimmed.match(/(\d{2})\.(\d{2})\.(\d{4})/);
  if (deMatch) {
    const [_, dd, mm, yyyy] = deMatch;
    return `${yyyy}-${mm}-${dd}`;
  }
  // Fallback: extract YYYY, MM, DD in any order
  const y = trimmed.match(/(\d{4})/);
  const m = trimmed.match(/(?:^|\D)(\d{2})(?:\D|$)/);
  const d = trimmed.match(/(?:^|\D)(\d{2})(?:\D|$)/);
  if (y && m && d) {
    const yyyy = y[1];
    const mm = m[1];
    const dd = d[1];
    if (/^\d{4}$/.test(yyyy) && /^\d{2}$/.test(mm) && /^\d{2}$/.test(dd)) {
      return `${yyyy}-${mm}-${dd}`;
    }
  }
  return trimmed;
}

// Convert base64 string to ArrayBuffer
export function base64ToArrayBuffer(base64: string): ArrayBuffer {
  // Prefer Node.js Buffer when available (more tolerant), fallback to atob
  if (typeof Buffer !== "undefined") {
    const buf: any = Buffer.from(base64, "base64");
    const ab = new ArrayBuffer(buf.length);
    const view = new Uint8Array(ab);
    for (let i = 0; i < buf.length; i++) view[i] = buf[i];
    return ab;
  }
  if (typeof atob === "function") {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes.buffer;
  }
  // Last resort: empty buffer
  return new ArrayBuffer(0);
}

// Convert ArrayBuffer to base64 string
export function arrayBufferToBase64(buffer: ArrayBuffer): string {
  // Prefer Node.js Buffer when available
  if (typeof Buffer !== "undefined") {
    return Buffer.from(new Uint8Array(buffer)).toString("base64");
  }
  if (typeof btoa === "function") {
    const bytes = new Uint8Array(buffer);
    let binary = "";
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }
  return "";
}

// === Statistics Functions ===

// Get exercises that were skipped most frequently
export function getTopSkippedExercises(
  allSessions: Session[],
  exercises: Exercise[],
  limit: number = 10
): {
  name: string;
  count: number;
}[] {
  const skipCounts = new Map<string, number>();

  for (const session of allSessions) {
    for (const entry of session.entries) {
      if (entry.skipped) {
        const exerciseName =
          exercises.find((e) => e.id === entry.exerciseId)?.name ||
          entry.exerciseId;
        skipCounts.set(exerciseName, (skipCounts.get(exerciseName) || 0) + 1);
      }
    }
  }

  return Array.from(skipCounts.entries())
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

// Get training frequency by month - returns Record<month, count>
export function getMonthlyTrainingFrequency(
  allSessions: Session[]
): Record<string, number> {
  const frequencyMap: Record<string, number> = {};

  for (const session of allSessions) {
    const month = session.date.slice(0, 7); // YYYY-MM
    frequencyMap[month] = (frequencyMap[month] || 0) + 1;
  }

  return frequencyMap;
}

// Get daily training frequency
export function getDailyTrainingFrequency(
  allSessions: Session[]
): Record<string, number> {
  const frequencyMap: Record<string, number> = {};

  for (const session of allSessions) {
    frequencyMap[session.date] = (frequencyMap[session.date] || 0) + 1;
  }

  return frequencyMap;
}

// Get exercise volume history (sets × reps × weight)
// Returns: Record<exerciseId, array of {date, volume}>
export function getExerciseVolumeHistory(
  allSessions: Session[]
): Record<string, { date: string; volume: number }[]> {
  const result: Record<string, { date: string; volume: number }[]> = {};

  for (const session of allSessions) {
    for (const entry of session.entries) {
      if (entry.skipped) continue;

      const volume = entry.sets.reduce(
        (sum, set) => sum + (set.weight || 0) * (set.reps || 0),
        0
      );

      if (!result[entry.exerciseId]) {
        result[entry.exerciseId] = [];
      }
      result[entry.exerciseId].push({ date: session.date, volume });
    }
  }

  return result;
}

// Get personal records by exercise
// Returns: Record<exerciseId, {date, weight, reps}>
export function getExercisePRs(
  allSessions: Session[]
): Record<string, { date: string; weight: number; reps: number }> {
  const prs: Record<string, { date: string; weight: number; reps: number }> =
    {};

  for (const session of allSessions) {
    for (const entry of session.entries) {
      if (entry.skipped) continue;

      for (const set of entry.sets) {
        const prev = prs[entry.exerciseId];
        if (
          !prev ||
          (set.weight || 0) > prev.weight ||
          ((set.weight || 0) === prev.weight && (set.reps || 0) > prev.reps)
        ) {
          prs[entry.exerciseId] = {
            date: session.date,
            weight: set.weight || 0,
            reps: set.reps || 0,
          };
        }
      }
    }
  }

  return prs;
}

// Get exercise progression data
// Returns: Record<exerciseId, array of {date, maxWeight, avgWeight, avgReps}>
export function getExerciseProgression(
  allSessions: Session[]
): Record<
  string,
  { date: string; maxWeight: number; avgWeight: number; avgReps: number }[]
> {
  const result: Record<
    string,
    { date: string; maxWeight: number; avgWeight: number; avgReps: number }[]
  > = {};

  for (const session of allSessions) {
    for (const entry of session.entries) {
      if (entry.skipped) continue;

      const weights = entry.sets.map((s) => s.weight || 0);
      const reps = entry.sets.map((s) => s.reps || 0);

      if (weights.length === 0 || reps.length === 0) continue;

      const maxWeight = Math.max(...weights);
      const avgWeight = weights.reduce((a, b) => a + b, 0) / weights.length;
      const avgReps = reps.reduce((a, b) => a + b, 0) / reps.length;

      if (!result[entry.exerciseId]) {
        result[entry.exerciseId] = [];
      }

      result[entry.exerciseId].push({
        date: session.date,
        maxWeight,
        avgWeight,
        avgReps,
      });
    }
  }

  return result;
}

import ExcelJS from "exceljs";
import { Exercise, Session } from "./types";
import { arrayBufferToBase64, base64ToArrayBuffer } from "./utils";

/**
 * Updates an existing XLSX file with new training sessions.
 * Creates/overwrites an "App-Data" sheet with session history.
 * ExcelJS version preserves existing sheets and formatting.
 */
export async function updateXLSXWithSessions(
  base64Data: string,
  sessions: Session[],
  exercises: Exercise[]
): Promise<string> {
  try {
    const arrayBuffer = base64ToArrayBuffer(base64Data);
    const workbook = new ExcelJS.Workbook();
    // ExcelJS expects a Buffer on Node.js - cast to any to bypass type checking
    await workbook.xlsx.load(new Uint8Array(arrayBuffer) as any);

    // NOTE: We don't create/update "App-Data" sheet for now
    // The export to Einheit columns is the main feature
    // Skip creating hidden sheets for now to avoid conflicts with protected names

    // Write to buffer and convert to base64
    const outputBuffer = (await workbook.xlsx.writeBuffer()) as any;
    // Convert Node Buffer to ArrayBuffer
    const arr = new ArrayBuffer(outputBuffer.length);
    const view = new Uint8Array(arr);
    for (let i = 0; i < outputBuffer.length; i++) {
      view[i] = outputBuffer[i];
    }
    return arrayBufferToBase64(arr);
  } catch (error) {
    console.error("Error updating XLSX:", error);
    return base64Data;
  }
}

/**
 * Exports XLSX with training session data written to Einheit sheets.
 * Loads the provided XLSX file, writes training data to available Einheit columns,
 * and returns the modified workbook as an ArrayBuffer.
 *
 * Uses ExcelJS for all operations - preserves existing formatting and structure.
 */
export async function exportXLSXWithFormatting(
  base64Data: string,
  sessions: Session[],
  exercises: Exercise[]
): Promise<ArrayBuffer> {
  try {
    const arrayBuffer = base64ToArrayBuffer(base64Data);
    const workbook = new ExcelJS.Workbook();
    // ExcelJS expects a Buffer on Node.js - cast to any to bypass type checking
    await workbook.xlsx.load(new Uint8Array(arrayBuffer) as any);

    // Remove protected named ranges that might cause conflicts
    // The Excel file has a "History" defined name that's protected
    if ((workbook as any).definedNames) {
      const definedNames = (workbook as any).definedNames || {};
      // Remove the "History" defined name if it exists
      if (definedNames.History) {
        delete definedNames.History;
      }
      // Also try to remove any defined names that might conflict
      Object.keys(definedNames).forEach((key) => {
        if (
          key &&
          typeof key === "string" &&
          (key.includes("History") || key.includes("history"))
        ) {
          delete definedNames[key];
        }
      });
    }

    // ONLY export to the first sheet - continuation sheets have different exercises/dates
    // Determine how many Einheit columns are available, then take that many most recent sessions

    // Use only the first 'Einheit' sheet
    const einheitSheets = workbook.worksheets.filter((ws) =>
      ws.name.toLowerCase().includes("einheit")
    );

    // Helper to extract plain text from ExcelJS cell values, handling richText
    const getCellText = (val: any): string => {
      if (val == null) return "";
      if (typeof val === "string") return val;
      if (typeof val === "number") return String(val);
      if (typeof val === "object") {
        const anyVal: any = val as any;
        if (Array.isArray(anyVal.richText)) {
          try {
            return anyVal.richText.map((r: any) => r.text ?? "").join("");
          } catch {
            return "";
          }
        }
        if (typeof anyVal.text === "string") return anyVal.text;
        if (anyVal.result != null) return String(anyVal.result);
      }
      return String(val ?? "");
    };

    if (einheitSheets.length > 0) {
      const worksheet = einheitSheets[0];
      // Find Einheit columns: look for WH/KG column pairs
      // Strategy: Find all "WH" cells and check if the next cell is "KG"
      const einheitCols: Record<number, { whCol: number; kgCol: number }> = {};

      // Scan all header rows (1-20) for WH/KG pairs
      worksheet.eachRow((row, rowNumber) => {
        if (rowNumber <= 20) {
          row.eachCell((cell, colNumber) => {
            const cellValue = getCellText(cell.value).toLowerCase().trim();
            const nextCell = row.getCell(colNumber + 1);
            const nextValue = getCellText(nextCell.value).toLowerCase().trim();

            if (cellValue === "wh" && nextValue === "kg") {
              einheitCols[colNumber] = {
                whCol: colNumber,
                kgCol: colNumber + 1,
              };
            }
          });
        }
      });

      if (Object.keys(einheitCols).length > 0) {
        // Determine number of sessions to export based on detected Einheit columns
        const maxSessions = Object.keys(einheitCols).length;

        // Take up to maxSessions most recent sessions
        const recentSessions = sessions
          .sort((a, b) => b.date.localeCompare(a.date))
          .slice(0, maxSessions)
          .reverse(); // Reverse to get chronological order

        const chunk = recentSessions;

        // removed debug log: exporting sessions summary

        // Find exercise start row
        // Look for "Satz 1" / "Satz: 1" text, which indicates the start of actual exercise data rows
        // This is more reliable than looking for "Sätze:" header
        let startIndex = 0;
        worksheet.eachRow((row, rowNumber) => {
          if (startIndex === 0) {
            row.eachCell((cell) => {
              const v = getCellText(cell.value).toLowerCase();
              if (v.includes("satz") && (v.includes(": 1") || v.includes(" 1"))) {
                startIndex = rowNumber;
              }
            });
          }
        });

        if (startIndex === 0) {
          // Fallback: find "Sätze:" in a row that has exercise data (where column 1 or 2 has a number or text)
          worksheet.eachRow((row, rowNumber) => {
            if (startIndex === 0 && rowNumber > 7) {
              let hasSatze = false;
              let hasExerciseId = false;
              row.eachCell((cell, colNumber) => {
                const v = getCellText(cell.value).toLowerCase();
                if (v === "sätze:" || v === "satze:") hasSatze = true;
                if (colNumber === 1) {
                  const numVal = Number(getCellText(cell.value));
                  if (!isNaN(numVal) && numVal > 0) hasExerciseId = true;
                }
              });
              if (hasSatze && hasExerciseId) {
                startIndex = rowNumber;
              }
            }
          });
        }

        // removed debug log: exercise start row
        
        // Find Datum row (row with "Datum" label)
        let datumRowIdx = -1;
        worksheet.eachRow((row, rowNumber) => {
          if (datumRowIdx === -1 && rowNumber < 20) {
            // Only check first 20 rows
            row.eachCell((cell) => {
              const cellValue = getCellText(cell.value).toLowerCase();
              if (cellValue.includes("datum")) {
                datumRowIdx = rowNumber;
              }
            });
          }
        });
        
        // removed debug log: datum row index

        // Process each session in this chunk
        const sortedCols = Object.keys(einheitCols)
          .map((k) => parseInt(k))
          .sort((a, b) => a - b);

        // removed debug log: sorted Einheit columns

        for (let sIdx = 0; sIdx < chunk.length; sIdx++) {
          const session = chunk[sIdx];
          const whColNumber = sortedCols[sIdx];
          if (!whColNumber) {
            // warn: session had no column found (suppressed)
            continue;
          }

          const colInfo = einheitCols[whColNumber];
          if (!colInfo) {
            // warn: missing colInfo for computed column (suppressed)
            continue;
          }

          const whWriteCol = colInfo.whCol;
          const kgWriteCol = colInfo.kgCol;
          
          // removed debug log: writing session columns

          // Write date to Datum row (same column as Einheit WH column)
          if (datumRowIdx > 0) {
            const dateCell = worksheet.getCell(datumRowIdx, whWriteCol);
            dateCell.value = new Date(session.date);
            dateCell.numFmt = "DD.MM.YYYY";
            // removed debug log: date write confirmation
          }

          // Write exercise data
          exercises.forEach((exercise, exerciseIdx) => {
            const entry = session.entries.find(
              (e) => e.exerciseId === exercise.id
            );
            const sortedSets = entry
              ? [...entry.sets].sort((a, b) => a.setNumber - b.setNumber)
              : [];

            const exerciseRowIdx1 = startIndex + exerciseIdx * 2;
            const exerciseRowIdx2 = startIndex + exerciseIdx * 2 + 1;

            // Write exercise notes to column C (index 3) for both rows
            // Only write if it's the first session (to update the exercise definition)
            if (sIdx === 0 && exercise.notes) {
              const notesCell1 = worksheet.getCell(exerciseRowIdx1, 3);
              const notesCell2 = worksheet.getCell(exerciseRowIdx2, 3);
              notesCell1.value = exercise.notes;
              notesCell2.value = exercise.notes;
            }

            // Ensure WH (reps) cells are independent per row
            try {
              worksheet.unMergeCells(
                exerciseRowIdx1,
                whWriteCol,
                exerciseRowIdx2,
                whWriteCol
              );
            } catch {}

            // Satz 1 (Set 1)
            if (sortedSets.length > 0) {
              const set1 = sortedSets[0];
              const repsCell = worksheet.getCell(exerciseRowIdx1, whWriteCol);
              const weightCell = worksheet.getCell(exerciseRowIdx1, kgWriteCol);

              repsCell.value = Number(set1.reps);
              repsCell.numFmt = "0"; // Ensure numeric format
              weightCell.value = Number(set1.weight);
              weightCell.numFmt = "0.0"; // Ensure numeric format with decimal

              // Merge KG cell across Satz 1 and Satz 2 rows so weight appears once for both
              try {
                worksheet.mergeCells(
                  exerciseRowIdx1,
                  kgWriteCol,
                  exerciseRowIdx2,
                  kgWriteCol
                );
              } catch {}
              
              // removed debug log: satz 1 write confirmation
            }

            // Satz 2 (Set 2)
            if (sortedSets.length > 1) {
              const set2 = sortedSets[1];
              const repsCell = worksheet.getCell(exerciseRowIdx2, whWriteCol);
              repsCell.value = Number(set2.reps);
              repsCell.numFmt = "0";
              // Do NOT write a separate KG value for Satz 2.
              // The KG cell is merged across both rows and uses Satz 1 weight.
            }
          });
        }
      } else {
        console.warn("❌ No Einheit columns found!");
      }
    }

    // Normalize header cell values to plain strings for compatibility in tests
    try {
      if (einheitSheets.length > 0) {
        const ws = einheitSheets[0];
        ws.eachRow((row, rowNumber) => {
          if (rowNumber > 30) return;
          row.eachCell((cell) => {
            const text = getCellText(cell.value);
            if (
              text &&
              (text.toLowerCase().includes("einheit") ||
                text.toLowerCase() === "wh" ||
                text.toLowerCase() === "kg") &&
              typeof cell.value !== "string"
            ) {
              cell.value = text;
            }
          });
        });
      }
    } catch {}

    // Write to buffer
    let outputBuffer: any;
    try {
      outputBuffer = (await workbook.xlsx.writeBuffer()) as any;
    } catch (error: any) {
      // If we get an error about protected names, try clearing them
      if (error.message && error.message.includes("protected")) {
        console.warn("Clearing protected names before retry:", error.message);
        // Try to clear all defined names
        if ((workbook as any).definedNames) {
          (workbook as any).definedNames = {};
        }
        // Try again
        outputBuffer = (await workbook.xlsx.writeBuffer()) as any;
      } else {
        throw error;
      }
    }

    // Convert Node Buffer to ArrayBuffer
    const arr = new ArrayBuffer(outputBuffer.length);
    const view = new Uint8Array(arr);
    for (let i = 0; i < outputBuffer.length; i++) {
      view[i] = outputBuffer[i];
    }
    return arr;
  } catch (error) {
    console.error("Error exporting XLSX:", error);
    throw error;
  }
}

import ExcelJS from "exceljs";
import { Exercise, Session } from "./types";
import { base64ToArrayBuffer } from "./utils";

// Import-Regeln für XLSX-Parser:
// - Eine Einheit (Session) wird nur importiert, wenn mindestens vier Übungen in mindestens einem Satz eine Wiederholungszahl (Reps) hat.
// - Hat eine zu importierende Einheit für eine Übung in beiden Sätzen keinen Zahlenwert (Reps), wird diese Übung in dieser Einheit mit skipped: true markiert.

function parseExcelDate(value: any): string | null {
  if (!value) return null;

  if (typeof value === "string") {
    const trimmed = value.trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
      return trimmed;
    }

    if (/^\d{1,2}\.\d{1,2}\.\d{2,4}$/.test(trimmed)) {
      const parts = trimmed.split(".");
      let year = parts[2];
      if (year.length === 2) {
        year = "20" + year;
      }
      const month = parts[1].padStart(2, "0");
      const day = parts[0].padStart(2, "0");
      return `${year}-${month}-${day}`;
    }

    if (/^\d{1,2}\/\d{1,2}\/\d{2,4}$/.test(trimmed)) {
      const parts = trimmed.split("/");
      const month = parts[0].padStart(2, "0");
      const day = parts[1].padStart(2, "0");
      let year = parts[2];
      if (year.length === 2) {
        year = "20" + year;
      }
      return `${year}-${month}-${day}`;
    }
  }

  if (typeof value === "number") {
    const excelEpoch = new Date(1899, 11, 30);
    const date = new Date(excelEpoch.getTime() + value * 86400000);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  try {
    const date = new Date(value);
    if (!isNaN(date.getTime())) {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, "0");
      const day = String(date.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    }
  } catch (e) {
    return null;
  }

  return null;
}

/**
 * Parses an XLSX ArrayBuffer and returns exercises, metadata, and sessions.
 *
 * Import-Regeln:
 * - Eine Trainingseinheit (Session) wird nur importiert, wenn mindestens eine Übung in mindestens einem Satz eine Wiederholungszahl (Reps) hat.
 * - Hat eine zu importierende Einheit für eine Übung in beiden Sätzen keinen Zahlenwert (Reps), wird diese Übung in dieser Einheit mit `skipped: true` markiert.
 *
 * @param arrayBuffer XLSX file as ArrayBuffer
 * @returns { exercises, metadata, sessions }
 */
export async function parseXLSX(arrayBuffer: ArrayBuffer): Promise<{
  exercises: Exercise[];
  metadata: {
    trainingGoal?: string;
    legalNotice?: string;
    notes?: string;
  };
  sessions: Session[];
}> {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(new Uint8Array(arrayBuffer));

  console.log(
    "Available sheets:",
    workbook.worksheets.map((ws) => ws.name)
  );

  // Process all sheets to gather sessions
  const allSessions: Session[] = [];
  let exercises: Exercise[] = [];
  const metadata: {
    trainingGoal?: string;
    legalNotice?: string;
    notes?: string;
  } = {};

  // Track the latest header date seen across all sheets (not filtered by reps)
  let globalLatestHeaderDate: string | null = null;

  // Helper to get the max header date in a sheet (first ~100 rows to ensure we find all header rows)
  // Helper to get the max header date in a sheet
  const getMaxHeaderDateInData = (data: any[][]): string | null => {
    let maxDate: string | null = null;
    const limit = Math.min(100, data.length);
    const currentYear = new Date().getFullYear();
    for (let r = 0; r < limit; r++) {
      const row = data[r];
      if (!row) continue;
      for (let c = 0; c < row.length; c++) {
        const dateStr = parseExcelDate(row[c]);
        if (!dateStr) continue;

        // Sanity check: only accept dates that are reasonable.
        // Reject dates before 1990 or more than 1 year in the future (filters out bogus Excel serials).
        const year = parseInt(dateStr.split("-")[0]);
        if (year < 1990 || year > currentYear + 1) {
          continue;
        }

        if (!maxDate || dateStr > maxDate) {
          maxDate = dateStr;
        }
      }
    }
    return maxDate;
  };

  // Process each sheet
  for (const worksheet of workbook.worksheets) {
    const sheetName = worksheet.name;
    console.log(`\n=== Processing sheet: ${sheetName} ===`);

    // Convert exceljs worksheet to 2D array with correct column indices
    const data: any[][] = [];
    worksheet.eachRow((row: ExcelJS.Row) => {
      const rowData: any[] = [];
      row.eachCell(
        { includeEmpty: true },
        (cell: ExcelJS.Cell, colNumber: number) => {
          rowData[colNumber - 1] = cell.value;
        }
      );
      data.push(rowData);
    });

    console.log(`Sheet has ${data.length} rows`);

    // Only parse exercises from the first sheet (they're the same across all sheets)
    if (exercises.length === 0) {
      const parsedData = parseSheetData(data);
      exercises = parsedData.exercises;
      Object.assign(metadata, parsedData.metadata);
    }

    // Update global header latest date for cross-sheet interpolation
    const headerMax = getMaxHeaderDateInData(data);
    if (
      headerMax &&
      (!globalLatestHeaderDate || headerMax > globalLatestHeaderDate)
    ) {
      globalLatestHeaderDate = headerMax;
    }

    // Parse sessions from this sheet using the latest header date across sheets
    const sessions = parseSessionsFromSheet(
      data,
      exercises,
      globalLatestHeaderDate
    );

    // Append all sessions, but ensure no duplicate dates
    sessions.forEach((session) => {
      let baseDate = session.date;
      let uniqueDate = baseDate;
      let counter = 2;
      while (allSessions.some((s) => s.date === uniqueDate)) {
        uniqueDate = `${baseDate}-${counter}`;
        counter++;
      }
      if (uniqueDate !== session.date) {
        session.entries.forEach((entry) => {
          entry.date = uniqueDate;
        });
        session.date = uniqueDate;
      }
      allSessions.push(session);
    });
  }

  console.log(`\n=== Final Results ===`);
  console.log(`Total exercises: ${exercises.length}`);
  console.log(`Total sessions: ${allSessions.length}`);
  if (allSessions.length > 0) {
    console.log("Session dates:", allSessions.map((s) => s.date).sort());
  }

  // Clean up suggestedWeight for exercises that have actual training data
  const exercisesWithTraining = new Set<string>();
  allSessions.forEach((session) => {
    session.entries.forEach((entry) => {
      if (entry.sets && entry.sets.length > 0) {
        exercisesWithTraining.add(entry.exerciseId);
      }
    });
  });

  exercises.forEach((exercise) => {
    if (exercisesWithTraining.has(exercise.id) && exercise.suggestedWeight) {
      console.log(
        `Clearing suggestedWeight for "${exercise.name}" (has training history)`
      );
      exercise.suggestedWeight = undefined;
    }
  });

  const exercisesWithSuggestedWeight = exercises.filter(
    (e) => e.suggestedWeight !== undefined
  );
  if (exercisesWithSuggestedWeight.length > 0) {
    console.log(
      `Final: ${exercisesWithSuggestedWeight.length} exercises retained suggestedWeight (no training history)`
    );
  }

  return { exercises, metadata, sessions: allSessions };
}

function getLatestDate(sessions: Session[]): string | null {
  if (sessions.length === 0) return null;
  return sessions
    .map((s) => s.date)
    .filter(Boolean)
    .sort()
    .slice(-1)[0];
}

function parseSheetData(data: any[][]): {
  exercises: Exercise[];
  metadata: {
    trainingGoal?: string;
    legalNotice?: string;
    notes?: string;
  };
} {
  const exercises: Exercise[] = [];
  const metadata: {
    trainingGoal?: string;
    legalNotice?: string;
    notes?: string;
  } = {};

  const ignoredKeywords = [
    "trainingsziel",
    "training goal",
    "rechtliche hinweise",
    "legal notice",
    "hinweise",
    "notizen",
    "notes",
    "bei bedarf",
    "copyright",
  ];

  const isMetadataRow = (text: string): boolean => {
    const lowerText = text.toLowerCase().trim();
    return ignoredKeywords.some((keyword) => lowerText.includes(keyword));
  };

  let startIndex = 0;
  for (let i = 0; i < data.length; i++) {
    const row = data[i];

    const secondCell = String(row[1] || "")
      .toLowerCase()
      .trim();
    const normalizedSecondCell = secondCell
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");

    if (
      normalizedSecondCell === "ubungen" ||
      normalizedSecondCell === "exercises" ||
      secondCell === "übungen"
    ) {
      startIndex = i + 1;
      break;
    }

    const cellBStr = String(row[1] || "").trim();

    if (cellBStr && isMetadataRow(cellBStr)) {
      const value = String(row[2] || "").trim();
      const lowerCellB = cellBStr.toLowerCase();

      if (
        lowerCellB.includes("trainingsziel") ||
        lowerCellB.includes("training goal")
      ) {
        metadata.trainingGoal = value;
      } else if (
        lowerCellB.includes("rechtliche") ||
        lowerCellB.includes("legal")
      ) {
        metadata.legalNotice = value;
      } else if (
        lowerCellB.includes("hinweise") ||
        lowerCellB.includes("notiz") ||
        lowerCellB.includes("notes")
      ) {
        if (!metadata.legalNotice) {
          metadata.notes = value;
        }
      }
    }
  }

  console.log(
    `Starting to parse exercises from row ${startIndex}, total rows: ${data.length}`
  );

  // Detect Einheit 1 columns to extract suggested weights
  // Look for "Einheit" header with "1" in the next column
  let einheit1WhCol: number | null = null;
  let einheit1KgCol: number | null = null;

  for (const row of data) {
    if (!row) continue;
    for (let colIdx = 0; colIdx < row.length; colIdx++) {
      const cell = row[colIdx];
      if (typeof cell === "string" && cell.toLowerCase().includes("einheit")) {
        const nextCell = row[colIdx + 1];
        if (nextCell != null && String(nextCell).trim() === "1") {
          // Einheit: is at colIdx, "1" is at colIdx+1
          // In many templates, the WH column aligns with the "Einheit:" column itself
          // and KG is the next column to the right
          einheit1WhCol = colIdx; // WH in the same column as "Einheit:"
          einheit1KgCol = colIdx + 1; // KG directly to the right
          console.log(
            `Detected Einheit 1: Einheit at col ${colIdx}, WH col ${einheit1WhCol}, KG col ${einheit1KgCol}`
          );
          break;
        }
      }
    }
    if (einheit1WhCol !== null) break;
  }

  // Exercises span 2 rows each (Satz 1 and Satz 2). Process only Satz 1 rows.
  // Start from first non-empty row and step by 2
  // However, ensure we don't miss the final exercise if it's at an odd index
  let firstExerciseRow = startIndex;
  for (let i = startIndex; i < data.length; i++) {
    const row = data[i];
    const cellBStr = String(row?.[1] || "").trim();
    if (cellBStr && !isMetadataRow(cellBStr)) {
      firstExerciseRow = i;
      break;
    }
  }

  console.log(
    `Starting exercise parse at row ${firstExerciseRow}, total data rows: ${data.length}`
  );
  console.log(
    `Column info: einheit1WhCol=${einheit1WhCol}, einheit1KgCol=${einheit1KgCol}`
  );

  let lastExerciseName: string | null = null;

  for (let i = firstExerciseRow; i < data.length; i++) {
    const row = data[i];

    if (!row || row.length === 0) {
      continue;
    }

    const cellBStr = String(row[1] || "").trim();

    // Skip header row and empty rows
    if (!cellBStr || cellBStr === "") {
      lastExerciseName = null; // Reset when we see a Satz 2 row (empty column B)
      continue;
    }

    // Skip metadata rows
    if (isMetadataRow(cellBStr)) {
      continue;
    }

    // Check if this looks like a header row (contains "Übung", "Exercise", etc.)
    const lowerB = cellBStr.toLowerCase();
    const normalizedB = lowerB.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    if (
      normalizedB === "ubungen" ||
      lowerB === "übungen" ||
      lowerB === "exercise" ||
      lowerB === "exercises" ||
      lowerB === "muskel"
    ) {
      continue;
    }

    // Skip if this is a Satz 2 row (same exercise as the previous row)
    if (lastExerciseName !== null && cellBStr === lastExerciseName) {
      continue;
    }

    // At this point, we have a new Satz 1 row - process it
    lastExerciseName = cellBStr;
    const exerciseName = cellBStr;
    const notes = String(row[2] || "").trim();

    // Skip if exercise name is not a valid string (corrupted data)
    if (
      typeof exerciseName !== "string" ||
      exerciseName === "[object Object]"
    ) {
      continue;
    }

    // Extract suggested weight from Einheit 1 KG column (first row of exercise pair)
    let suggestedWeight: number | undefined;
    if (einheit1KgCol !== null && row[einheit1KgCol] != null) {
      const weightValue = row[einheit1KgCol];
      const parsedWeight = parseFloat(String(weightValue).trim());
      if (!isNaN(parsedWeight) && parsedWeight > 0) {
        suggestedWeight = parsedWeight;
      }
    }

    exercises.push({
      id: `exercise-${i}`,
      name: exerciseName,
      notes: notes || undefined,
      order: exercises.length,
      suggestedWeight,
    });
  }

  console.log(`Parsed ${exercises.length} exercises`);
  if (exercises.some((e) => e.suggestedWeight)) {
    console.log(
      `  ${
        exercises.filter((e) => e.suggestedWeight).length
      } exercises have suggested weights`
    );
  }

  return { exercises, metadata };
}

/**
 * Interpolates dates for training sessions where dates are missing.
 * Splits dates evenly between known date points.
 * Returns array with both the session info and whether date was interpolated.
 *
 * Example:
 * Input:  [{date: '2025-11-18'}, {date: null}, {date: null}, {date: '2025-11-21'}]
 * Output: [{date: '2025-11-18', interpolated: false}, {date: '2025-11-19', interpolated: true}, {date: '2025-11-20', interpolated: true}, {date: '2025-11-21', interpolated: false}]
 */
function interpolateSessionDates(
  sessions: Array<{ whCol: number; kgCol: number; date: string | null }>,
  latestKnownDate?: string | null
): Array<{
  whCol: number;
  kgCol: number;
  date: string;
  interpolated: boolean;
}> {
  if (sessions.length === 0) {
    return [];
  }

  const result: Array<{
    whCol: number;
    kgCol: number;
    date: string;
    interpolated: boolean;
  }> = [];
  let i = 0;

  while (i < sessions.length) {
    // If this session has a date, add it to result
    if (sessions[i].date) {
      result.push({
        whCol: sessions[i].whCol,
        kgCol: sessions[i].kgCol,
        date: sessions[i].date!,
        interpolated: false,
      });
      i++;
      continue;
    }

    // Collect consecutive undated sessions
    const unddatedSessions = [sessions[i]];
    i++;
    while (i < sessions.length && !sessions[i].date) {
      unddatedSessions.push(sessions[i]);
      i++;
    }

    // Find the next dated session or use today as fallback
    const nextDatedSession = sessions[i];
    const lastDatedSession =
      result.length > 0 ? result[result.length - 1] : null;

    if (!lastDatedSession && !nextDatedSession) {
      // No dates at all - continue after latest known date across sheets
      const base = latestKnownDate ? new Date(latestKnownDate) : new Date();
      const startDate = new Date(base);
      for (let j = 0; j < unddatedSessions.length; j++) {
        const date = new Date(startDate);
        date.setDate(date.getDate() + (j + 1));
        const iso = date.toISOString().split("T")[0];
        result.push({
          whCol: unddatedSessions[j].whCol,
          kgCol: unddatedSessions[j].kgCol,
          date: iso,
          interpolated: true,
        });
      }
      console.log(
        `  → All undated sessions assigned after ${latestKnownDate ?? "today"}`
      );
      continue;
    }

    if (!lastDatedSession && nextDatedSession) {
      // First sessions are undated, next one has date
      const startDate = new Date(nextDatedSession.date!);
      const endDate = new Date(nextDatedSession.date!);
      const daysBetween = 0;
      const intervalDays =
        unddatedSessions.length > 0
          ? Math.max(1, Math.floor(daysBetween / (unddatedSessions.length + 1)))
          : 1;

      for (let j = 0; j < unddatedSessions.length; j++) {
        const date = new Date(startDate);
        date.setDate(
          date.getDate() - (unddatedSessions.length - j) * intervalDays
        );
        result.push({
          whCol: unddatedSessions[j].whCol,
          kgCol: unddatedSessions[j].kgCol,
          date: date.toISOString().split("T")[0],
          interpolated: true,
        });
      }
      continue;
    }

    if (lastDatedSession && !nextDatedSession) {
      // Continuation sheet end: place undated sessions sequentially after the latest known date across sheets
      const baseDateStr =
        latestKnownDate && latestKnownDate > lastDatedSession.date
          ? latestKnownDate
          : lastDatedSession.date;
      const base = new Date(baseDateStr);
      for (let j = 0; j < unddatedSessions.length; j++) {
        const date = new Date(base);
        date.setDate(date.getDate() + (j + 1));
        result.push({
          whCol: unddatedSessions[j].whCol,
          kgCol: unddatedSessions[j].kgCol,
          date: date.toISOString().split("T")[0],
          interpolated: true,
        });
      }
      continue;
    }

    // Both before and after have dates - interpolate
    const startDate = new Date(lastDatedSession!.date);
    const endDate = new Date(nextDatedSession!.date || Date.now());
    const daysBetween = Math.floor(
      (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24)
    );
    const intervalDays = Math.max(
      1,
      Math.floor(daysBetween / (unddatedSessions.length + 1))
    );

    for (let j = 0; j < unddatedSessions.length; j++) {
      const date = new Date(startDate);
      date.setDate(date.getDate() + (j + 1) * intervalDays);
      result.push({
        whCol: unddatedSessions[j].whCol,
        kgCol: unddatedSessions[j].kgCol,
        date: date.toISOString().split("T")[0],
        interpolated: true,
      });
    }
  }

  return result;
}

/**
 * Parsed jede Sheet-Tabelle und erzeugt Sessions gemäß folgender Regeln:
 * - Eine Einheit (Session) wird nur importiert, wenn mindestens eine Übung in mindestens einem Satz eine Wiederholungszahl (Reps) hat.
 * - Hat eine Übung in einer importierten Einheit in beiden Sätzen keine Wiederholungszahl, wird sie mit `skipped: true` markiert.
 */
function parseSessionsFromSheet(
  data: any[][],
  exercises: Exercise[],
  latestKnownDate?: string | null
): Session[] {
  const sessions: Session[] = [];
  let hasAnyDateInSheet = false;

  // Find exercise start row
  let startIndex = 0;
  for (let i = 0; i < data.length; i++) {
    const row = data[i];
    const secondCell = String(row?.[1] ?? "")
      .toLowerCase()
      .trim();
    const normalizedSecondCell = secondCell
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");
    if (
      normalizedSecondCell === "ubungen" ||
      normalizedSecondCell === "exercises" ||
      normalizedSecondCell === "muskel"
    ) {
      // Use the last detected header so we align with the actual training table
      startIndex = i + 1;
    }
  }

  // Fallback: some continuation sheets omit the "Übungen" header. Use the first
  // row where a Satz label appears as the starting point (row contains training
  // data for the first exercise).
  if (startIndex === 0) {
    for (let i = 0; i < data.length; i++) {
      const row = data[i];
      const satzCell = String(row?.[5] ?? "").toLowerCase();
      if (satzCell.includes("satz")) {
        startIndex = i;
        break;
      }
    }
  }

  // Map Einheit numbers by column (if present)
  // NOTE: "Einheit:" is in one column, the number is in the next
  // But WH is in the "Einheit:" column and KG is in the number column
  // So we store the EINHEIT COLUMN (where WH is), not the number column
  const einheitByCol: Record<number, string> = {};
  let headerRowIdx = -1;
  for (let rowIdx = 0; rowIdx < data.length; rowIdx++) {
    const row = data[rowIdx];
    if (!row) continue;
    let foundAnyEinheit = false;
    for (let colIdx = 0; colIdx < row.length; colIdx++) {
      const cell = row[colIdx];
      if (typeof cell === "string" && cell.toLowerCase().includes("einheit")) {
        foundAnyEinheit = true;
        const value = row[colIdx + 1];
        if (value != null && String(value).trim() !== "") {
          if (headerRowIdx === -1) {
            headerRowIdx = rowIdx;
          }
          einheitByCol[colIdx] = String(value).trim(); // FIX: store the Einheit HEADER column, not the number column
        }
      }
    }
  }

  // First, create sessions for ALL Einheiten (based on column structure)
  // Then fill in dates where available
  const sessionsByCol: Map<
    number,
    {
      whCol: number;
      kgCol: number;
      date: string | null;
      einheitNumber?: string;
    }
  > = new Map();

  // Initialize sessions for all Einheit columns
  for (const [colIdxStr, einheitNum] of Object.entries(einheitByCol)) {
    const colIdx = parseInt(colIdxStr);
    // Einheit: is at colIdx (header). In our sheets, WH aligns with the "Einheit:" column
    // and KG is the immediate next column to the right.
    const whCol = colIdx;
    const kgCol = colIdx + 1;

    sessionsByCol.set(colIdx, {
      whCol: whCol,
      kgCol: kgCol,
      date: null,
      einheitNumber: einheitNum,
    });
  }

  // Create set of valid Einheit columns for validation later
  const einheitCols = new Set(
    Object.keys(einheitByCol).map((k) => parseInt(k))
  );

  // Fill in dates from the Datum row
  // Search MORE BROADLY - check ALL rows up to startIndex + buffer to handle test data structures
  const dateSearchLimit = Math.min(startIndex + 5, data.length);
  for (let rowIdx = 0; rowIdx < dateSearchLimit; rowIdx++) {
    const row = data[rowIdx];
    if (!row) continue;

    const hasDateLabel = row.some((cell) => {
      if (typeof cell !== "string") return false;
      const lower = cell.toLowerCase();
      return lower.includes("datum") || lower.includes("date");
    });

    if (!hasDateLabel) continue;

    row.forEach((cell, colIdx) => {
      if (colIdx < 5) return; // Training data starts at later columns
      if (typeof cell === "string") {
        const lower = cell.toLowerCase();
        if (lower.includes("datum") || lower.includes("date")) {
          return;
        }
      }

      const dateStr = parseExcelDate(cell);
      if (!dateStr) return;

      // Try to find the session at this column
      let session = sessionsByCol.get(colIdx);

      if (!session) {
        // Try the next column (date might be one column to the left of Einheit header)
        session = sessionsByCol.get(colIdx + 1);
        if (session) {
          session.date = dateStr;
        }
      }

      if (!session) {
        // Try to find the nearest Einheit column to the right
        for (
          let searchCol = colIdx + 1;
          searchCol <= colIdx + 8;
          searchCol += 2
        ) {
          if (einheitCols.has(searchCol)) {
            session = sessionsByCol.get(searchCol);
            if (session) {
              session.date = dateStr;
              break;
            }
          }
        }
      }

      if (session) {
        session.date = dateStr;
        hasAnyDateInSheet = true;
      } else {
        // Create new session if no Einheit was defined for this column
        sessionsByCol.set(colIdx, {
          whCol: colIdx,
          kgCol: colIdx + 1,
          date: dateStr,
          einheitNumber: einheitByCol[colIdx] ?? einheitByCol[colIdx + 1],
        });
        hasAnyDateInSheet = true;
      }
    });
  }

  // Secondary pass: detect dates anywhere in the header area, but ignore small integers
  // IMPORTANT: Only search rows AFTER the Datum row to avoid parsing header row numbers as dates
  // ONLY SEARCH COLUMNS THAT HAVE ACTUAL EINHEITEN
  const headerRowLimit = Math.min(startIndex, data.length);
  const datumRowIndex = 11;

  for (let rowIdx = datumRowIndex + 1; rowIdx < headerRowLimit; rowIdx++) {
    const row = data[rowIdx];
    if (!row) continue;

    for (let colIdx = 0; colIdx < row.length; colIdx++) {
      if (colIdx < 5) continue; // Ignore metadata columns

      // ONLY check columns that have Einheiten defined
      if (!einheitCols.has(colIdx)) continue;

      const cell = row[colIdx];
      if (typeof cell === "number" && cell < 60) {
        continue;
      }

      const dateStr = parseExcelDate(cell);
      if (!dateStr) continue;

      const session = sessionsByCol.get(colIdx);
      if (session && !session.date) {
        // Update session with found date
        session.date = dateStr;
        hasAnyDateInSheet = true;
      }
    }
  }

  // Convert map to array, sorted by column index
  const trainingSessions = Array.from(sessionsByCol.values()).sort(
    (a, b) => a.whCol - b.whCol
  );

  // CRITICAL FIX: Only keep sessions that correspond to actual Einheit columns
  // Filter out any stray sessions created in wrong columns
  const validSessions = trainingSessions.filter((s) => {
    // Keep session if:
    // 1. Its column has an Einheit, OR
    // 2. It's within the expected range (col 5 to col 21, step 2)
    if (einheitCols.has(s.whCol)) return true;

    // Fallback: keep if it looks like it's in the typical Einheit position (odd columns 7, 9, 11, etc)
    if (s.whCol >= 7 && s.whCol <= 21 && (s.whCol - 7) % 2 === 0) return true;

    return false;
  });

  if (validSessions.length === 0) {
    return sessions;
  }

  // Interpolate missing dates: fill gaps between known dates
  const sessionsWithInterpolatedDates = interpolateSessionDates(
    validSessions,
    latestKnownDate
  );

  console.log(
    `Found ${sessionsWithInterpolatedDates.length} training sessions in this sheet`
  );

  for (const {
    whCol,
    kgCol,
    date,
    interpolated: interpolatedFlag = false,
  } of sessionsWithInterpolatedDates) {
    let hasAnyReps = false; // true if any exercise yields at least one set
    const entries: any[] = [];

    console.log(
      `  → Checking session at whCol=${whCol}, kgCol=${kgCol}, date=${date}, exerciseCount=${exercises.length}`
    );

    for (let exerciseIdx = 0; exerciseIdx < exercises.length; exerciseIdx++) {
      const exercise = exercises[exerciseIdx];
      const exerciseRowIdx1 = startIndex + exerciseIdx * 2;
      const exerciseRowIdx2 = startIndex + exerciseIdx * 2 + 1;
      if (exerciseRowIdx1 >= data.length) continue;

      const exerciseRow1 = data[exerciseRowIdx1];
      const exerciseRow2 =
        exerciseRowIdx2 < data.length ? data[exerciseRowIdx2] : null;

      const isRow1Empty =
        !exerciseRow1 ||
        ((exerciseRow1[whCol] == null ||
          String(exerciseRow1[whCol]).trim() === "") &&
          (exerciseRow1[kgCol] == null ||
            String(exerciseRow1[kgCol]).trim() === ""));
      const isRow2Empty =
        !exerciseRow2 ||
        ((exerciseRow2[whCol] == null ||
          String(exerciseRow2[whCol]).trim() === "") &&
          (exerciseRow2[kgCol] == null ||
            String(exerciseRow2[kgCol]).trim() === ""));

      const reps1 = exerciseRow1?.[whCol];
      const weight1 = exerciseRow1?.[kgCol];
      const reps2 = exerciseRow2 ? exerciseRow2[whCol] : null;
      const weight2Raw = exerciseRow2 ? exerciseRow2[kgCol] : null;

      const weight2 =
        (weight2Raw === undefined || weight2Raw === null) &&
        reps2 != null &&
        reps2 !== "/" &&
        String(reps2).trim() !== ""
          ? weight1
          : weight2Raw;

      // Check if both reps are empty/missing (for skipped unit detection)
      const reps1Str = reps1 != null ? String(reps1).trim() : "";
      const reps2Str = reps2 != null ? String(reps2).trim() : "";
      const bothRepsEmpty =
        (reps1Str === "" || reps1Str === "/") &&
        (reps2Str === "" || reps2Str === "/");

      const sets: any[] = [];

      // Satz 1
      if (reps1 != null) {
        const repsStr1 = String(reps1).trim();
        // Reject ranges like "10-12" which are suggested reps, not actual training data
        if (repsStr1.includes("-")) {
          // This is a suggested range, skip it
        } else {
          const weightStr1 = weight1 != null ? String(weight1).trim() : "";
          const weightMissing =
            weightStr1 === "" || weightStr1 === "/" || weight1 == null;
          if (repsStr1 !== "/" && repsStr1 !== "") {
            const repsNum1 = parseInt(repsStr1);
            const weightNum1Raw = parseFloat(weightStr1.replace(",", "."));
            const weightNum1 = !isNaN(weightNum1Raw) ? weightNum1Raw : 0;
            const hasValidWeight = weightNum1 > 0;
            if (
              !isNaN(repsNum1) &&
              repsNum1 > 0 &&
              (hasValidWeight || weightMissing)
            ) {
              sets.push({
                setNumber: 1,
                weight: hasValidWeight ? weightNum1 : 0,
                reps: repsNum1,
              });
            }
          }
        }
      }

      // Satz 2
      if (reps2 != null) {
        const repsStr2 = String(reps2).trim();
        // Reject ranges like "10-12" which are suggested reps, not actual training data
        if (repsStr2.includes("-")) {
          // This is a suggested range, skip it
        } else {
          const weightStr2 = weight2 != null ? String(weight2).trim() : "";
          const weightMissing =
            weightStr2 === "" || weightStr2 === "/" || weight2 == null;
          if (repsStr2 !== "/" && repsStr2 !== "") {
            const repsNum2 = parseInt(repsStr2);
            const weightNum2Raw = parseFloat(weightStr2.replace(",", "."));
            const weightNum2 = !isNaN(weightNum2Raw) ? weightNum2Raw : 0;
            const hasValidWeight = weightNum2 > 0;
            if (
              !isNaN(repsNum2) &&
              repsNum2 > 0 &&
              (hasValidWeight || weightMissing)
            ) {
              sets.push({
                setNumber: 2,
                weight: hasValidWeight ? weightNum2 : 0,
                reps: repsNum2,
              });
            }
          }
        }
      }

      if (sets.length > 0) {
        hasAnyReps = true;
      }

      const entry: any = {
        id: `entry-${date}-${exercise.id}`,
        exerciseId: exercise.id,
        date,
        sets,
      };
      // Mark as skipped if both reps are empty/missing (per import rules)
      if (bothRepsEmpty) {
        entry.skipped = true;
      }
      entries.push(entry);
    }

    // Session only counts if at least one exercise has reps
    if (!hasAnyReps) {
      console.log(
        `⚠️  Filtering out session at col ${whCol}, date ${date}: no reps found in any exercise`
      );
      continue;
    }

    // Per import rules: session is valid if at least one exercise has reps
    // (hasAnyReps is already checked above, so we can add the session)
    const sessionToAdd = { date, entries, dateInterpolated: interpolatedFlag };
    sessions.push(sessionToAdd);
  }

  console.log(`Imported ${sessions.length} sessions from this sheet`);
  return sessions;
}

